        "landing.faq2a": "It's the risk we take most seriously, because a wrong note doesn't look like a mistake. From a source, Mika writes only what the source says, and when the text doesn't settle a point, the doubtful point doesn't appear. From a typed topic, the notes are those of a reference course, and the quiz makes you check them.",
