        "legal.eyebrow": "Micabo · iPhone, Android and site",
        "legal.updated": "Last updated: {date}.",
        "legal.updatedDate": "23 October 2026",
        "legal.privacy.metaTitle": "Privacy",
        "legal.privacy.metaDescription": "What Micabo keeps about you, on iPhone, on Android and on the site, and what you can do with it.",
        "legal.privacy.heading": "Privacy policy",
        "legal.privacy.linkLabel": "privacy policy",
        "legal.privacy.intro1": "This policy describes the data Micabo processes when you use the site [[site]], the iPhone app (identifier {bundle}, distributed on the App Store) or the Android app (package {package}, distributed on Google Play). The three clients share the same account and the same database. It also applies if you do not yet have an account and are only browsing the site.",
        "legal.privacy.intro2": "The controller is {editor}. For any question, correction or deletion: [[contact]].",
        "legal.privacy.whatTitle": "What Micabo is",
        "legal.privacy.whatBody": "Micabo turns a course (PDF, photo, document, video) into a sheet and flashcards, then brings them back before you forget them. An exam mode tightens revision as a date approaches. You can share a course with friends, or keep it to yourself.",
        "legal.privacy.dataTitle": "What data we process",
        "legal.privacy.dataAccount": "**The account.** Email address, identifiers provided by Apple or Google if you choose those sign-in methods, and a username. We do not store your password: email sign-in uses a link, not a secret we would keep.",
        "legal.privacy.dataSchool": "**The academic path.** Country of study, level, subjects, and school if you give it. This is used to write the sheet in the right language and the right system, and to show you classmates from the same school if a course is shared.",
        "legal.privacy.dataCourses": "**Your courses.** The files or links you upload, the text extracted from them, the generated sheets and cards, diagram images, exams (name, date, target grade) and the revision history (when a card comes back, how you rated it).",
        "legal.privacy.dataFriends": "**Friends.** Friend requests, your friends list, and the visibility you set on each course at import: you only, your friends, or classmates at your school. There is no public catalogue where a stranger would stumble on your sheets.",
        "legal.privacy.dataSubscription": "**The subscription.** The status of your Pro access (active, trial, cancelled), not your card number. Payment is collected by Apple on iPhone (App Store), by Google on Android (Google Play), by Stripe on the site. RevenueCat holds the right, so that the iPhone, Android and the browser agree.",
        "legal.privacy.dataWaitlist": "**The waitlist.** If you leave your address before you have an account, we keep it to notify you of the opening, together with the page you came from. It is not linked to an account and is not visible through the app.",
        "legal.privacy.dataFeedback": "**Feedback.** If you send a bug or an idea from the app, we keep the message, the type (bug or idea), and the link to your account, so we can reply. They are kept for 24 months, then deleted. They are not used to profile you.",
        "legal.privacy.dataUsage": "**Generation usage.** A counter per day and per function (sheet, cards, explanation), without the course content. It is used to limit abuse, not to profile you.",
        "legal.privacy.dataDirectory": "**The directory.** Your username and, if you have given it, your school. That is what a friend or classmate sees, not your email or your preferences.",
        "legal.privacy.dataDevice": "**What stays on the device.** On iPhone and on Android, some pieces (occlusion images, audio for a card) may never leave the phone. Answers from the onboarding path stay on the device first, then are written to the database once the account is opened.",
        "legal.privacy.dataNoSell": "We do not sell your data. We do not show advertising. We do not train a language model on your courses, unless an explicit setting offers that one day — and that setting does not exist today.",
        "legal.privacy.whyTitle": "Why we process them",
        "legal.privacy.whyLead": "The legal bases, within the meaning of the GDPR:",
        "legal.privacy.whyContract": "**Performance of the contract** — creating the account, importing a course, writing the sheet and the cards, reviewing them, syncing the iPhone and Android apps and the site, managing the subscription.",
        "legal.privacy.whyLegitimate": "**Legitimate interest** — securing the service, preventing abuse, diagnosing a fault, measuring the site's audience in aggregated form, and reading the feedback you send us. This interest does not come before yours: the isolation is in the database, not only in the application.",
        "legal.privacy.whyLegal": "**Legal obligation** — retaining what billing or accounting require, for the prescribed time.",
        "legal.privacy.whyConsent": "**Consent** — when you choose to share a course, open the camera, or sign in with Apple or Google.",
        "legal.privacy.accessTitle": "Who has access",
        "legal.privacy.accessBody": "Your courses are readable only by you, unless you have shared them. Every request to the database is evaluated with your identity: there is no query that can ask for someone else's courses. Feedback you send is read by the team, at [[contact]]. Nobody else has access to it from the application.",
        "legal.privacy.accessLead": "Service providers see some of the data, solely to provide the service:",
        "legal.privacy.accessSupabase": "**Supabase** (European Union, Stockholm region) — account, database, files.",
        "legal.privacy.accessVercel": "**Vercel** — hosting of the site, technical logs (IP address, URL) and audience measurement: the number of page views, the page you came from, the country and the device type, without a cookie and without an identifier that follows you. Processing may take place outside the European Union, under the provider's standard contractual clauses.",
        "legal.privacy.accessApple": "**Apple and Google** — if you sign in with them, or if you pay on the App Store (Apple) or on Google Play (Google).",
        "legal.privacy.accessStripe": "**Stripe** — payment on the site.",
        "legal.privacy.accessRevenuecat": "**RevenueCat** — subscription status, shared between the iPhone, Android and the site.",
        "legal.privacy.accessFal": "**fal.ai and the models it calls** (today, language models, notably from Google) — the text or image of your course, for the time it takes to write the sheet or the cards. They are not allowed to use it for anything other than that generation.",
        "legal.privacy.accessYoutube": "**YouTube / Google** — if you import a video, we read its metadata and subtitles.",
        "legal.privacy.accessTransfer": "Some of these providers are established outside the European Union. The transfer then takes place only to provide the service, and relies on the safeguards provided by the GDPR (adequacy decision or the provider's standard contractual clauses).",
        "legal.privacy.cookiesTitle": "Cookies and trackers",
        "legal.privacy.cookiesWeb": "The site sets the cookies needed for the session (to recognise you from one page to the next once you are signed in) and an interface-language preference cookie (`micabo.ui_locale`), kept for one year, which remembers the language you chose for the interface. Once you are signed in, a `micabo.learner` cookie, kept for one year, remembers on this browser your exact level and the grades given during onboarding: it is used only to write your lessons at the right level. We do not set an audience-measurement cookie, nor an advertising cookie, nor cross-site tracking. The site does count its visits, but without writing anything on your device: the measurement keeps a page view, its origin, a country, a device type, and nothing that would let us recognise you from one visit to the next or on another site. That is why there is no consent banner: there is nothing to refuse on that side.",
        "legal.privacy.cookiesIos": "The iPhone and Android apps do not use cookies. They keep a session token in the device's protected storage: the Keychain on iPhone, the app's private storage on Android.",
        "legal.privacy.retentionTitle": "How long we keep them",
        "legal.privacy.retentionWhile": "For as long as the account exists. Feedback is deleted after 24 months at the latest. If you delete it, from Settings on the site or in the iPhone and Android apps, or by writing to us, we erase the profile, the courses (including the extracted text), the sheets, the cards, the history, the exams, the friendships, the usage counters, the feedback and any address left on the waitlist.",
        "legal.privacy.retentionShared": "A course you have shared disappears for your friends when you delete it. A friend who has already reviewed your cards keeps their own history, not your document.",
        "legal.privacy.retentionAfter": "After deletion, providers retain what the law or their contract requires: Stripe, Apple or Google invoices, a RevenueCat subscription identifier, technical logs (Vercel, Supabase) for a few weeks. fal.ai receives the text for the time it takes to write the sheet; we do not ask it to keep it.",
        "legal.privacy.rightsTitle": "Your rights",
        "legal.privacy.rightsBody": "You can access your data, correct it, export it, object to processing, or request erasure. To download a copy: Settings → “Download my data”. To delete the account: Settings → “Delete account”, on the site or in the iPhone and Android apps. You can also write to [[contact]]. We reply within a month.",
        "legal.privacy.rightsCnil": "You can also lodge a complaint with the CNIL (cnil.fr).",
        "legal.privacy.minorsTitle": "Minors",
        "legal.privacy.minorsBody": "Micabo is aimed at students, including those in secondary school. We do not ask for a date of birth. If you are under fifteen, use of the service must be with the agreement of a person with parental authority. We do not use a minor's data for advertising, nor for commercial profiling.",
        "legal.privacy.iosTitle": "The iPhone and Android apps, in addition to the site",
        "legal.privacy.iosBody": "The apps may ask for access to your photos, your files or your camera to import a course. This is not required: the site accepts an uploaded file. Notifications, if you allow them, are only used to remind you of a review. The same account opens the iPhone app, the Android app and the site.",
        "legal.privacy.changesTitle": "Changes",
        "legal.privacy.changesBody": "If this policy changes in a material way, we update the date at the top of the page. Continued use after that date applies to the new version, unless the law requires a separate agreement.",
        "legal.privacy.changesAlso": "The [[terms]] complement this text.",
        "legal.terms.metaTitle": "Terms of use",
        "legal.terms.metaDescription": "The rules of the Micabo service, for iPhone, Android and the site: account, courses, subscription, liabilities.",
        "legal.terms.heading": "Terms of use",
        "legal.terms.linkLabel": "terms of use",
        "legal.terms.intro1": "These terms govern the use of Micabo — the site [[site]], the iPhone app ({bundle}, on the App Store) and the Android app ({package}, on Google Play). By creating an account or using the service, you accept them. If you do not agree, do not open an account.",
        "legal.terms.intro2": "The publisher is {editor}. Contact: [[contact]].",
        "legal.terms.serviceTitle": "The service",
        "legal.terms.serviceBody": "Micabo reads a course document you upload and writes a sheet and flashcards from it. It brings them back according to spaced repetition (the same SM-2 rule on iPhone, on Android and on the site). You can set an exam date: the revision plan then tightens towards that day. The same account opens all three clients.",
        "legal.terms.servicePro": "Part of the service is available without a subscription. Pro access (courses and cards beyond the free cap, according to the offer shown at the time of purchase) is paid.",
        "legal.terms.accountTitle": "The account",
        "legal.terms.accountBody": "You can sign in with Apple, Google, or a link sent by email. You are responsible for access to your mailbox and to those third-party accounts. One account per person.",
        "legal.terms.accountDelete": "You can delete the account from Settings, on the site or in the iPhone and Android apps. This erases your courses, your cards and your history. Deleting the account does not cancel a subscription taken on the App Store or on Google Play: cancel it in the store. Purchases already collected by Apple, Google or Stripe remain subject to their refund rules.",
        "legal.terms.coursesTitle": "Your courses",
        "legal.terms.coursesOwn": "You keep ownership of what you upload. You give us only the limited, revocable right to read it, store it and transform it into a sheet and cards, to provide you the service — including by sending it to a language model for the duration of the generation.",
        "legal.terms.coursesRights": "You upload only documents you have the right to use. A handout from your teacher, your notes, a video whose import is authorised: yes. An entire copied work, someone else's assignment, illegal content: no. We may remove a course or close an account that breaks this rule.",
        "legal.terms.coursesShare": "Visibility is decided at import. A private course stays with you. A shared course is visible only to the people you have chosen (friends, or classmates at the school). This is not a library open to everyone.",
        "legal.terms.notTitle": "What Micabo is not",
        "legal.terms.notBody": "The sheet and the cards are generated automatically. They can be wrong, omit a passage, or misread a scan. Micabo is not a teacher, nor a grade guarantee. You remain responsible for what you learn and for what you submit on exam day.",
        "legal.terms.notInvent": "We try not to invent a definition when the document does not carry one. That does not make the result infallible.",
        "legal.terms.subTitle": "The subscription",
        "legal.terms.subPrices": "Prices, duration and any trial are those shown before payment. They may change for new purchases; a subscription already in progress keeps its terms until renewal.",
        "legal.terms.subIos": "**On iPhone**, payment goes through the App Store: cancellation, renewal and refunds follow Apple's rules, and you manage or cancel the subscription in your Apple account settings (Settings → your name → Subscriptions). **On Android**, payment goes through Google Play: cancellation, renewal and refunds follow Google Play's rules, and you manage or cancel the subscription in the Google Play app (Payments & subscriptions → Subscriptions).",
        "legal.terms.subWeb": "**On the site**, payment goes through Stripe. Cancellation is done from the billing area indicated in the profile, or by writing to us. A trial, if offered, only becomes a charge if you let it run to the end.",
        "legal.terms.subBoth": "Pro access bought on one side applies on the others: the same account is Pro on iPhone, on Android and on the site. A payment incident may open a grace period; we do not close access in the first hour.",
        "legal.terms.forbidTitle": "What you do not do",
        "legal.terms.forbidHarm": "Use the service to harm someone, harass, or cheat in a way that violates your school's rules.",
        "legal.terms.forbidAccess": "Attempt to access another account's courses, to circumvent the isolation, or to deliberately overload the service.",
        "legal.terms.forbidResell": "Resell access, extract the service through a bot beyond normal human use, or copy Micabo to make a competing product from our generations.",
        "legal.terms.forbidIllegal": "Upload illegal or hateful content, or content that infringes someone else's privacy.",
        "legal.terms.availTitle": "Availability",
        "legal.terms.availBody": "We do our best to keep the apps and the site reachable. Maintenance, a provider outage (host, model, store) or a generation error may interrupt the service. We do not offer a guarantee of academic results, nor of uninterrupted availability.",
        "legal.terms.liabilityTitle": "Liability",
        "legal.terms.liabilityConsumer": "If you are a consumer, your statutory rights (warranty, mediation, unfair terms) apply and these terms do not set them aside.",
        "legal.terms.liabilityLimit": "Beyond that, Micabo is not liable for grades obtained, an incomplete sheet, forgetting on the day, or indirect damage (lost time, a missed exam). Our liability, if it were upheld for a breach attributable to us, is limited to the amount you paid us over the last twelve months — except in cases of gross negligence, fraud, or injury to a person's physical integrity.",
        "legal.terms.minorsTitle": "Minors",
        "legal.terms.minorsBody": "If you are under fifteen, a person with parental authority must accept these terms and supervise use. Sharing a course with friends remains your responsibility, and theirs.",
        "legal.terms.lawTitle": "Governing law",
        "legal.terms.lawBody": "These terms are governed by French law. In the event of a dispute, and after an attempt at written resolution to [[contact]], the French courts have jurisdiction — subject to any consumer-protection rules that would be more favourable to you.",
        "legal.terms.changesTitle": "Changes",
        "legal.terms.changesBody": "We may update these terms. The date at the top of the page is authoritative. A change that affects the price of a subscription in progress is announced to you before renewal.",
        "legal.terms.changesAlso": "The [[privacy]] describes the processing of your data.",
        "articles.shared.navAria": "Pages",
        "articles.shared.nextTitle": "Read next",
        "articles.shared.ctaTitle": "Type a topic, see what it becomes.",
        "articles.shared.ctaBody": "On the site as on iPhone, with the same account and the same lessons.",
        "articles.method.metaTitle": "The method: spaced repetition and active recall, inside a lesson",
        "articles.method.metaDescription": "Rereading a course doesn't make you remember it. What you retrieve from memory sticks, especially when the question comes back just before forgetting. How a Micabo lesson applies active recall and spacing, with the real intervals.",
        "articles.method.h1": "Rereading isn't enough. Remembering is.",
        "articles.method.lead1": "A page reread four times gives a feeling of mastery that doesn't survive the exam sheet. What improves is recognition: \"yes, I've seen this\". And recognition is not what an exam asks for.",
        "articles.method.lead2": "What sticks is what you had to **retrieve from memory**, and what comes back **just before you forget it**. Two old ideas, measured for over a century, and two ideas painful to apply by hand. That's what a Micabo lesson does for you.",
        "articles.method.activeTitle": "Active recall: the question before the answer",
        "articles.method.active1": "Testing yourself works better than rereading, even when you get it wrong. The effort of retrieval is what strengthens the trace: an answer you search for three seconds beats one you read in one.",
        "articles.method.active2": "That's why each theme of a lesson ends with **a question**, and each stage with a checkpoint: you don't move on without retrieving what you just read. And a missed question doesn't vanish, it becomes a flashcard.",
        "articles.method.spacingTitle": "Spacing: coming back at the last useful moment",
        "articles.method.spacing1": "Without review, what you keep from a course drops to almost nothing in a month. Each recall resets the counter to a hundred, and the following drop is **slower than the last**. Reviewing at the right time doesn't take more time: it takes less, as memory settles.",
        "articles.method.spacing2": "What matters isn't the shape of each curve, it's **where they part**: the first review. What a lesson's flashcards automate is the choice of that moment, card by card.",
        "articles.method.lessonTitle": "The lesson first, the flashcards after",
        "articles.method.lesson1": "A flashcard assumes you already understood. Testing yourself on a concept you haven't read means learning an answer by heart without knowing what it's about. That's why Mika first writes **the notes** of each theme: short, with the keywords in evidence, and a box for what to remember.",
        "articles.method.lessonFigure": "A theme's notes, as Mika writes them: the keyword in color, the definition, **what to remember** in a box. The same blocks as in the app.",
        "articles.method.lesson2": "Then come the quiz and the flashcards, drawn from those notes and not from the raw document. You read, you answer, and only then do the cards come back, at the pace of spacing.",
        "articles.method.plannerTitle": "What Micabo computes at each rating",
        "articles.method.planner1": "Flashcards are scheduled with **SM-2**, Anki's rule in its default settings. A new card goes through short steps, {steps}, before moving to days. Then each rating multiplies the interval by an ease specific to the card, starting at {ease} and moving with your answers.",
        "articles.method.planner2": "Three buttons: Again, Good, Easy. \"I know / I don't\" doesn't tell apart the card retrieved with effort from the one that came by itself, and that gap decides the next date. Here is what the three buttons announce on a new card:",
        "articles.method.buttonsCaption": "The intervals are computed by the app's scheduler, not written by hand.",
        "articles.method.planner3": "The interval is written on the button **before** you press. A scheduler that decides on its own soon gets disobeyed: you rate \"easy\" to go faster, the card leaves for three weeks, and you rediscover it on exam day.",
        "articles.method.stepMinutes": "{n} min",
        "articles.method.stepJoin": ", then ",
        "articles.method.formatsTitle": "Five ways to be asked about the same notes",
        "articles.method.formats1": "Active recall isn't limited to front and back. On one theme, the quiz asks multiple choice, true or false, fill in the gap, put in order, match. Questions come from your notes, and each answer says at once whether it's right, and why.",
        "articles.method.formatsFigure": "A quiz question, the real one: answer, it corrects you. **The five forms come from the same notes**, from the simplest to the most demanding.",
        "articles.method.limitsTitle": "What the method doesn't do",
        "articles.method.limits1": "Spaced repetition places reviews. It doesn't understand for you, it doesn't write an essay, and it doesn't catch up a chapter started the night before: there's no spacing possible over one night.",
        "articles.method.limits2": "It also ignores dates, by construction: SM-2 doesn't know an exam is in three weeks. That's exactly what the [[exam]] completes.",
        "articles.method.examLink": "exam mode",
        "articles.method.note": "A lesson opens freely at any step: nothing forces you to finish the path in one go. All spacing asks is that you come back when the cards say so.",
        "articles.exam.metaTitle": "Exam mode: a date, days left, a mock exam",
        "articles.exam.metaDescription": "Give your exam date, Micabo counts the days on every lesson it covers. The mock exam is timed, with no corrections during the paper, graded on your country's scale, and your mistakes become flashcards.",
        "articles.exam.h1": "You give the date. Micabo counts the days, and trains you.",
        "articles.exam.lead1": "Learning a lesson and passing an exam are not the same thing. On the day, you write against the clock, without seeing whether you're right, and you're graded on a scale. None of that happens in an ordinary review.",
        "articles.exam.lead2": "Exam mode gives your lessons what they lack: **a date**, and a test that looks like the real one. You set the day, pick the lessons it covers, and train with mock exams.",
        "articles.exam.dateTitle": "A date, and the days left",
        "articles.exam.date1": "An exam is a name, a day, and the lessons it covers. From there, every lesson on the syllabus carries its countdown, on Home, in the lessons list and in the Exam tab: \"12 days left\" reads before you open anything.",
        "articles.exam.date2": "An exam can cover several lessons, and a lesson can be in several exams. It's always **the closest** that shows: it's the first constraint. Past the day, the exam moves to the past ones, and there's nothing to switch off.",
        "articles.exam.mockTitle": "The mock exam: like the real thing",
        "articles.exam.mock1": "You pick the length, {durations}, and the lessons. Mika writes a fresh paper, from the simplest to the most demanding, in the five question forms. The clock runs, the chosen answer highlights with no verdict, you go back, you change your mind. At zero, the paper hands itself in.",
        "articles.exam.mockFigure": "The paper handed in: the grade on your scale, **lesson by lesson**, and the answer key for each question below.",
        "articles.exam.mock2": "The answer key comes at the end, question by question: what you answered, the right answer, and why. That's where you learn, not during the test, which is why the test corrects nothing along the way.",
        "articles.exam.gradeTitle": "Graded on your scale",
        "articles.exam.grade1": "A mark out of twenty, out of ten, a percentage, a letter, steps: the scale follows your country, set in your profile. A French 14/20, an American A and a German 1.3 don't compare, and a universal score would mean nothing anywhere.",
        "articles.exam.grade2": "Each lesson on the paper gets its own grade. That's what tells you where to go back: a lesson below the pass mark the day before the exam is a lesson to reopen, and its path is waiting.",
        "articles.exam.cardsTitle": "Mistakes become flashcards",
        "articles.exam.cards1": "A question missed on the mock exam doesn't stay on the paper. With one tap it joins its lesson's flashcards, due tomorrow, and comes back at the pace of spacing until it sticks.",
        "articles.exam.cardsNote": "Nothing forces you to add them. But a mistake seen once and never again is exactly the one you repeat on the day.",
        "articles.exam.limitsTitle": "What exam mode doesn't do",
        "articles.exam.limits1": "It doesn't make time. Declaring an exam for tomorrow on a lesson you haven't opened gives an honest countdown and a hard paper, and Micabo shows them as they are rather than reassuring you.",
        "articles.exam.limits2": "Nor does it replace [[method]]: the notes, the quizzes and the flashcards do the work, the mock exam only measures it. If you come from Anki, the [[anki]] says precisely what changes.",
        "articles.exam.methodLink": "the method",
        "articles.exam.ankiLink": "comparison",
        "articles.exam.duration": "{minutes} min for {count} questions",
        "articles.exam.durationJoin": ", ",
        "articles.anki.metaTitle": "Micabo or Anki: what really changes",
        "articles.anki.metaDescription": "Anki is open, proven and excellent. Micabo writes the lesson from your source, its notes, quizzes and flashcards, and grades you on a mock exam. An honest comparison, including where Anki wins.",
        "articles.anki.eyebrow": "Comparison",
        "articles.anki.h1": "Micabo or Anki: what really changes",
        "articles.anki.lead1": "Anki is very good software. It's open, it has twenty years behind it and a community that documented everything. If you already use it and it suits you, you have no reason to switch.",
        "articles.anki.lead2": "The difference isn't in flashcard scheduling: **it's the same SM-2**. It's before, in the lesson you don't have to write, and after, in the mock exam and its date.",
        "articles.anki.tableTitle": "Line by line",
        "articles.anki.tableLead": "Three lines go to Anki, and they're written as they are.",
        "articles.anki.tableCaption": "Comparison of Micabo and Anki, criterion by criterion.",
        "articles.anki.colCriterion": "Criterion",
        "articles.anki.rowAlgo": "The algorithm",
        "articles.anki.rowAlgoMicabo": "SM-2, with Anki's default settings, three buttons.",
        "articles.anki.rowAlgoAnki": "SM-2 historically, FSRS today, and both are tunable.",
        "articles.anki.rowWrite": "Writing the cards",
        "articles.anki.rowWriteMicabo": "Mika writes them with the lesson, theme by theme. You read, you answer, they come back.",
        "articles.anki.rowWriteAnki": "Up to you. That's where most of the time goes.",
        "articles.anki.rowLesson": "Understanding before reviewing",
        "articles.anki.rowLessonMicabo": "Notes per theme, a quiz, a path of steps: the lesson before the cards.",
        "articles.anki.rowLessonAnki": "Nothing: Anki assumes you already understood.",
        "articles.anki.rowDate": "An exam date",
        "articles.anki.rowDateMicabo": "A countdown on each lesson, and mock exams graded on your scale.",
        "articles.anki.rowDateAnki": "No notion of a date. You push the deck forward by hand.",
        "articles.anki.rowQuestions": "Ways of being asked",
        "articles.anki.rowQuestionsMicabo": "Multiple choice, true or false, gap, ordering, matching, flashcards, mock exam.",
        "articles.anki.rowQuestionsAnki": "Front and back, and the card types you build yourself.",
        "articles.anki.rowPlatforms": "Platforms",
        "articles.anki.rowPlatformsMicabo": "iPhone and browser, the same account on both.",
        "articles.anki.rowPlatformsAnki": "Desktop, Android, iPhone, browser.",
        "articles.anki.rowDecks": "Ready-made decks",
        "articles.anki.rowDecksMicabo": "No catalog. Your lessons, and a demo lesson to start.",
        "articles.anki.rowDecksAnki": "Thousands of public decks, of uneven quality.",
        "articles.anki.rowStart": "Getting started",
        "articles.anki.rowStartMicabo": "A typed topic, a path to follow, a lesson finished the same evening.",
        "articles.anki.rowStartAnki": "Settings to understand before the first card.",
        "articles.anki.costTitle": "What Anki really costs: time",
        "articles.anki.cost1": "A useful Anki deck for a college course is two to four hours of typing per chapter: cutting up, phrasing one question per idea, not piling five things on one card. That work is instructive, denying it would be dishonest. But it's the work that makes you open Anki in September and not in November.",
        "articles.anki.costFigure": "A typed topic, a PDF, a photo, a recording, a video, pasted text: **everything goes in as is**. The typing disappears, the reading and the questions stay.",
        "articles.anki.cost2": "Micabo takes that step. The source becomes a lesson: notes per theme, a quiz, flashcards. You read, you answer, you fix what's wrong. It's still your work, but it starts at reading instead of a blank page.",
        "articles.anki.costNote": "The flip side is real: a generated note can be badly phrased or drawn from a badly read scan. That's why the notes come before the cards, and why Mika doesn't write a point the source doesn't mention. A note that's wrong doesn't look like a mistake.",
        "articles.anki.dateTitle": "What Anki doesn't do: the test",
        "articles.anki.date1": "That's the real mechanical difference. Anki brings cards back, indefinitely, without knowing there's a test on the 14th or what a timed paper looks like.",
        "articles.anki.date2": "In Micabo, you set the date, each lesson carries its countdown, and you sit timed mock exams, graded on your scale, whose mistakes come back as flashcards. [[exam]] explains how.",
        "articles.anki.examLink": "Exam mode",
        "articles.anki.pickTitle": "Which to pick",
        "articles.anki.pickAnki": "**Stay on Anki** if you like tuning your scheduler, if you want FSRS, if you're on Android, or if you value an open tool whose files you own.",
        "articles.anki.pickMicabo": "**Try Micabo** if what blocks you isn't reviewing but everything before it, understanding and making the questions, or if your studying is organized around exams rather than a continuous flow.",
        "articles.anki.pickBoth": "And if you hesitate: [[method]] is the same in both. It's what does the work, not the software carrying it.",
        "articles.anki.methodLink": "the method",
    ]

