        "landing.metaDescription": "Tape un sujet ou dépose un PDF, une photo, un audio, une vidéo. Mika écrit les notes, les quiz et les flashcards, et tu suis le chemin jusqu'au quiz final. Puis l'examen blanc, noté comme le vrai.",
