        "landing.faq1a": "Oui. Tes leçons ne sont exposées dans aucun catalogue : tu les vois seul. Le cloisonnement est dans la base, chaque requête est évaluée avec ton identité, donc il n'existe pas de requête qui puisse lire les leçons de quelqu'un d'autre.",
        "landing.faq2q": "Est-ce que Mika invente des choses ?",
        "landing.faq2a": "C'est le risque qu'on prend le plus au sérieux, parce qu'une note fausse ne ressemble pas à une erreur. Depuis un support, Mika n'écrit que ce que le support dit, et quand le texte ne tranche pas, le point douteux n'apparaît pas. Depuis un sujet tapé, les notes sont celles d'un cours de référence, et le quiz te le fait vérifier.",
