        "copy.heldBackNew": "{count, plural, one {# nouvelle carte pour plus tard — ton rythme du jour est atteint.} other {# nouvelles cartes pour plus tard — ton rythme du jour est atteint.}}",
        "copy.alreadySubscribed": "Tu es déjà abonné.",
        "legal.eyebrow": "Micabo · iPhone, Android et site",
        "legal.updated": "Dernière mise à jour : {date}.",
        "legal.updatedDate": "23 octobre 2026",
        "legal.privacy.metaTitle": "Confidentialité",
        "legal.privacy.metaDescription": "Ce que Micabo retient de vous, sur iPhone, sur Android et sur le site, et ce que vous pouvez en faire.",
        "legal.privacy.heading": "Politique de confidentialité",
        "legal.privacy.linkLabel": "politique de confidentialité",
        "legal.privacy.intro1": "Cette politique décrit les données que Micabo traite lorsque vous utilisez le site [[site]], l'application iPhone (identifiant {bundle}, distribuée sur l'App Store) ou l'application Android (paquet {package}, distribuée sur Google Play). Les trois clients partagent le même compte et la même base. Elle s'applique aussi si vous n'avez pas encore de compte et que vous consultez le site.",
        "legal.privacy.intro2": "Le responsable du traitement est {editor}. Pour toute question, correction ou suppression : [[contact]].",
        "legal.privacy.whatTitle": "Ce que Micabo est",
        "legal.privacy.whatBody": "Micabo transforme un cours (PDF, photo, document, vidéo) en fiche et en flashcards, puis les fait revenir avant que vous les oubliiez. Un mode examen resserre les révisions à l'approche d'une date. Vous pouvez partager un cours avec des amis, ou le garder pour vous.",
        "legal.privacy.dataTitle": "Quelles données nous traitons",
        "legal.privacy.dataAccount": "**Le compte.** Adresse e-mail, identifiants fournis par Apple ou Google si vous choisissez ces connexions, et un nom d'utilisateur. Nous ne stockons pas votre mot de passe : la connexion par courriel se fait par un lien, pas par un secret que nous garderions.",
        "legal.privacy.dataSchool": "**Le parcours scolaire.** Pays d'études, palier, matières, établissement si vous le donnez. Cela sert à écrire la fiche dans la bonne langue et le bon système, et à vous montrer les camarades du même établissement si un cours est partagé.",
        "legal.privacy.dataCourses": "**Vos cours.** Les fichiers ou liens que vous déposez, le texte qui en est extrait, les fiches et les cartes générées, les images de schémas, les examens (nom, date, note visée) et l'historique de révision (quand une carte revient, comment vous l'avez notée).",
        "legal.privacy.dataFriends": "**Les amis.** Les demandes d'ami, la liste de vos amis, et la visibilité que vous posez sur chaque cours au moment de l'import : vous seul, vos amis, ou les camarades de votre établissement. Il n'existe pas de catalogue public où un inconnu tomberait sur vos fiches.",
        "legal.privacy.dataSubscription": "**L'abonnement.** L'état de votre accès Pro (actif, essai, résilié), pas le numéro de votre carte. Le paiement est encaissé par Apple sur iPhone (App Store), par Google sur Android (Google Play), par Stripe sur le site. RevenueCat tient le droit, pour que l'iPhone, Android et le navigateur soient d'accord.",
        "legal.privacy.dataWaitlist": "**La liste d'attente.** Si vous laissez votre adresse avant d'avoir un compte, nous la gardons pour vous prévenir de l'ouverture, avec la page d'où vous venez. Elle n'est pas liée à un compte et n'est pas visible via l'application.",
        "legal.privacy.dataFeedback": "**Les retours.** Si vous envoyez un bug ou une idée depuis l'app, nous gardons le message, le type (bug ou idée), et le lien avec votre compte, pour y répondre. Ils restent 24 mois, puis sont effacés. Ils ne servent pas à vous profiler.",
        "legal.privacy.dataUsage": "**L'usage des générations.** Un compteur par jour et par fonction (fiche, cartes, explication), sans le contenu du cours. Il sert à limiter les abus, pas à vous profiler.",
        "legal.privacy.dataDirectory": "**L'annuaire.** Votre nom d'utilisateur et, si vous l'avez indiqué, votre établissement. C'est ce que voient un ami ou un camarade, pas votre e-mail ni vos préférences.",
        "legal.privacy.dataDevice": "**Ce qui reste sur l'appareil.** Sur iPhone et sur Android, certaines pièces (images d'occlusion, audio d'une carte) peuvent ne jamais quitter le téléphone. Les réponses du parcours d'accueil restent d'abord sur l'appareil, puis sont écrites en base une fois le compte ouvert.",
        "legal.privacy.dataNoSell": "Nous ne vendons pas vos données. Nous n'affichons pas de publicité. Nous n'entraînons pas un modèle de langage sur vos cours, sauf si un réglage explicite le propose un jour — et ce réglage n'existe pas aujourd'hui.",
        "legal.privacy.whyTitle": "Pourquoi nous les traitons",
        "legal.privacy.whyLead": "Les bases légales, au sens du RGPD :",
        "legal.privacy.whyContract": "**L'exécution du contrat** — créer le compte, importer un cours, écrire la fiche et les cartes, les réviser, synchroniser les apps iPhone et Android et le site, gérer l'abonnement.",
        "legal.privacy.whyLegitimate": "**L'intérêt légitime** — sécuriser le service, empêcher les abus, diagnostiquer une panne, mesurer l'audience du site de façon agrégée, et lire les retours que vous nous envoyez. Cet intérêt ne passe pas avant le vôtre : le cloisonnement est dans la base, pas seulement dans l'application.",
        "legal.privacy.whyLegal": "**L'obligation légale** — conserver ce que la facturation ou la comptabilité exigent, le temps prescrit.",
        "legal.privacy.whyConsent": "**Le consentement** — quand vous choisissez de partager un cours, d'ouvrir l'appareil photo, ou de vous connecter avec Apple ou Google.",
        "legal.privacy.accessTitle": "Qui y a accès",
        "legal.privacy.accessBody": "Vos cours ne sont lisibles que par vous, sauf si vous les avez partagés. Chaque requête à la base est évaluée avec votre identité : il n'existe pas de requête qui puisse demander les cours de quelqu'un d'autre. Les retours que vous envoyez sont lus par l'équipe, à l'adresse [[contact]]. Personne d'autre n'y a accès depuis l'application.",
        "legal.privacy.accessLead": "Des prestataires voient une partie des données, uniquement pour fournir le service :",
        "legal.privacy.accessSupabase": "**Supabase** (Union européenne, région Stockholm) — compte, base, fichiers.",
        "legal.privacy.accessVercel": "**Vercel** — hébergement du site, journaux techniques (adresse IP, URL) et mesure d'audience : le nombre de pages vues, la page d'où vous venez, le pays et le type d'appareil, sans cookie et sans identifiant qui vous suive. Le traitement peut avoir lieu hors de l'Union européenne, sous les clauses contractuelles types du prestataire.",
        "legal.privacy.accessApple": "**Apple et Google** — si vous vous connectez avec eux, ou si vous payez sur l'App Store (Apple) ou sur Google Play (Google).",
        "legal.privacy.accessStripe": "**Stripe** — paiement sur le site.",
        "legal.privacy.accessRevenuecat": "**RevenueCat** — état de l'abonnement, partagé entre l'iPhone, Android et le site.",
        "legal.privacy.accessFal": "**fal.ai et les modèles qu'il appelle** (aujourd'hui, des modèles de langage, notamment de Google) — le texte ou l'image de votre cours, le temps d'écrire la fiche ou les cartes. Ils n'ont pas le droit de s'en servir pour autre chose que cette génération.",
        "legal.privacy.accessYoutube": "**YouTube / Google** — si vous importez une vidéo, nous en lisons les métadonnées et les sous-titres.",
        "legal.privacy.accessTransfer": "Certains de ces prestataires sont établis hors de l'Union européenne. Le transfert n'a alors lieu que pour fournir le service, et s'appuie sur les garanties prévues par le RGPD (décision d'adéquation ou clauses contractuelles types du prestataire).",
        "legal.privacy.cookiesTitle": "Cookies et traceurs",
        "legal.privacy.cookiesWeb": "Le site pose les cookies nécessaires à la session (vous reconnaître d'une page à l'autre une fois connecté) et un cookie de préférence de langue d'interface (`micabo.ui_locale`), gardé un an, qui retient la langue que vous avez choisie pour l'interface. Une fois connecté, un cookie `micabo.learner`, gardé un an, retient sur ce navigateur votre palier exact et les moyennes données au parcours d'accueil : il ne sert qu'à écrire vos leçons au bon niveau. Nous ne posons pas de cookie de mesure d'audience, ni de publicité, ni de pistage inter-sites. Le site compte bien ses visites, mais sans rien écrire sur votre appareil : la mesure retient une page vue, sa provenance, un pays, un type d'appareil, et rien qui permette de vous reconnaître d'une visite à l'autre ou sur un autre site. C'est pour cela qu'il n'y a pas de bandeau de consentement : il n'y a rien à refuser de ce côté-là.",
        "legal.privacy.cookiesIos": "Les apps iPhone et Android n'utilisent pas de cookies. Elles gardent un jeton de session dans le stockage protégé de l'appareil : le trousseau sur iPhone, le stockage privé de l'app sur Android.",
        "legal.privacy.retentionTitle": "Combien de temps nous les gardons",
        "legal.privacy.retentionWhile": "Tant que le compte existe. Les retours partent au plus tard au bout de 24 mois. Si vous le supprimez, depuis Réglages sur le site ou dans les apps iPhone et Android, ou en nous écrivant, nous effaçons le profil, les cours (y compris le texte extrait), les fiches, les cartes, l'historique, les examens, les amitiés, les compteurs d'usage, les retours et l'adresse éventuellement laissée sur la liste d'attente.",
        "legal.privacy.retentionShared": "Un cours que vous avez partagé disparaît pour vos amis quand vous le supprimez. Un ami qui a déjà révisé vos cartes conserve son propre historique, pas votre document.",
        "legal.privacy.retentionAfter": "Après suppression, il reste chez des prestataires ce que la loi ou leur contrat impose : factures Stripe, Apple ou Google, identifiant d'abonnement RevenueCat, journaux techniques (Vercel, Supabase) quelques semaines. fal.ai reçoit le texte le temps d'écrire la fiche ; nous ne lui demandons pas de le conserver.",
        "legal.privacy.rightsTitle": "Vos droits",
        "legal.privacy.rightsBody": "Vous pouvez accéder à vos données, les corriger, les exporter, vous opposer à un traitement, ou demander l'effacement. Pour télécharger une copie : Réglages → « Télécharger mes données ». Pour effacer le compte : Réglages → « Supprimer le compte », sur le site ou dans les apps iPhone et Android. Vous pouvez aussi écrire à [[contact]]. Nous répondons dans le mois.",
        "legal.privacy.rightsCnil": "Vous pouvez aussi introduire une réclamation auprès de la CNIL (cnil.fr).",
        "legal.privacy.minorsTitle": "Mineurs",
        "legal.privacy.minorsBody": "Micabo s'adresse à des étudiants, y compris au lycée. Nous ne demandons pas la date de naissance. Si vous avez moins de quinze ans, l'usage du service doit se faire avec l'accord d'un titulaire de l'autorité parentale. Nous n'utilisons pas les données d'un mineur pour de la publicité, ni pour un profilage commercial.",
        "legal.privacy.iosTitle": "Les apps iPhone et Android, en plus du site",
        "legal.privacy.iosBody": "Les apps peuvent demander l'accès à vos photos, à vos fichiers ou à l'appareil photo pour importer un cours. Ce n'est pas obligatoire : le site accepte un fichier déposé. Les notifications, si vous les autorisez, ne servent qu'à vous rappeler une révision. Le même compte ouvre l'app iPhone, l'app Android et le site.",
        "legal.privacy.changesTitle": "Modifications",
        "legal.privacy.changesBody": "Si cette politique change de façon substantielle, nous mettons à jour la date en tête de page. L'usage continu après cette date vaut pour la nouvelle version, sauf si la loi exige un accord distinct.",
        "legal.privacy.changesAlso": "Les [[terms]] complètent ce texte.",
        "legal.terms.metaTitle": "Conditions d'utilisation",
        "legal.terms.metaDescription": "Les règles du service Micabo, pour l'iPhone, Android et le site : compte, cours, abonnement, responsabilités.",
        "legal.terms.heading": "Conditions d'utilisation",
        "legal.terms.linkLabel": "conditions d'utilisation",
        "legal.terms.intro1": "Ces conditions régissent l'usage de Micabo — le site [[site]], l'application iPhone ({bundle}, sur l'App Store) et l'application Android ({package}, sur Google Play). En créant un compte ou en utilisant le service, vous les acceptez. Si vous n'êtes pas d'accord, n'ouvrez pas de compte.",
        "legal.terms.intro2": "L'éditeur est {editor}. Contact : [[contact]].",
        "legal.terms.serviceTitle": "Le service",
        "legal.terms.serviceBody": "Micabo lit un document de cours que vous déposez et en écrit une fiche et des flashcards. Il les fait revenir selon une répétition espacée (la même règle SM-2 sur iPhone, sur Android et sur le site). Vous pouvez poser la date d'un examen : le plan de révision se resserre alors vers ce jour. Un même compte ouvre les trois clients.",
        "legal.terms.servicePro": "Une partie du service est accessible sans abonnement. L'accès Pro (cours et cartes au-delà du plafond gratuit, selon l'offre affichée au moment de l'achat) est payant.",
        "legal.terms.accountTitle": "Le compte",
        "legal.terms.accountBody": "Vous pouvez vous connecter avec Apple, Google, ou un lien envoyé par courriel. Vous êtes responsable de l'accès à votre boîte mail et à ces comptes tiers. Un seul compte par personne.",
        "legal.terms.accountDelete": "Vous pouvez supprimer le compte depuis Réglages, sur le site ou dans les apps iPhone et Android. Cela efface vos cours, vos cartes et votre historique. Supprimer le compte ne résilie pas un abonnement pris sur l'App Store ou sur Google Play : il se résilie dans la boutique. Les achats déjà encaissés par Apple, Google ou Stripe restent soumis à leurs règles de remboursement.",
        "legal.terms.coursesTitle": "Vos cours",
        "legal.terms.coursesOwn": "Vous gardez la propriété de ce que vous déposez. Vous nous donnez seulement le droit, limité et révocable, de le lire, de le stocker et de le transformer en fiche et en cartes, pour vous fournir le service — y compris en l'envoyant à un modèle de langage le temps de la génération.",
        "legal.terms.coursesRights": "Vous ne déposez que des documents que vous avez le droit d'utiliser. Un polycopié de votre professeur, vos notes, une vidéo dont l'import est autorisé : oui. Un ouvrage entier recopié, le devoir d'un autre, un contenu illégal : non. Nous pouvons retirer un cours ou fermer un compte qui casse cette règle.",
        "legal.terms.coursesShare": "La visibilité se décide à l'import. Un cours privé reste entre vous. Un cours partagé n'est visible que par les personnes que vous avez choisies (amis, ou camarades de l'établissement). Ce n'est pas une bibliothèque ouverte à tous.",
        "legal.terms.notTitle": "Ce que Micabo n'est pas",
        "legal.terms.notBody": "La fiche et les cartes sont générées automatiquement. Elles peuvent se tromper, omettre un passage, ou mal lire un scan. Micabo n'est pas un professeur, ni une garantie de note. Vous restez responsable de ce que vous apprenez et de ce que vous rendez le jour de l'examen.",
        "legal.terms.notInvent": "Nous nous efforçons de ne pas inventer une définition quand le document ne la porte pas. Ça ne rend pas le résultat infaillible.",
        "legal.terms.subTitle": "L'abonnement",
        "legal.terms.subPrices": "Les prix, la durée et l'essai éventuel sont ceux affichés avant le paiement. Ils peuvent changer pour les nouveaux achats ; un abonnement déjà en cours garde ses conditions jusqu'à son renouvellement.",
        "legal.terms.subIos": "**Sur iPhone**, le paiement passe par l'App Store : la résiliation, le renouvellement et les remboursements suivent les règles d'Apple, et l'abonnement se gère ou se résilie dans les réglages de votre compte Apple (Réglages → votre nom → Abonnements). **Sur Android**, le paiement passe par Google Play : la résiliation, le renouvellement et les remboursements suivent les règles de Google Play, et l'abonnement se gère ou se résilie dans l'app Google Play (Paiements et abonnements → Abonnements).",
        "legal.terms.subWeb": "**Sur le site**, le paiement passe par Stripe. La résiliation se fait depuis l'espace de facturation indiqué dans le profil, ou en nous écrivant. Un essai, s'il est proposé, ne se transforme en paiement que si vous le laissez aller à son terme.",
        "legal.terms.subBoth": "L'accès Pro acheté d'un côté vaut de l'autre : le même compte est Pro sur iPhone, sur Android et sur le site. Un incident de paiement peut ouvrir une période de grâce ; nous ne fermons pas l'accès à la première heure.",
        "legal.terms.forbidTitle": "Ce que vous ne faites pas",
        "legal.terms.forbidHarm": "Utiliser le service pour nuire à quelqu'un, harceler, ou tricher d'une façon qui viole le règlement de votre établissement.",
        "legal.terms.forbidAccess": "Tenter d'accéder aux cours d'un autre compte, de contourner le cloisonnement, ou de surcharger volontairement le service.",
        "legal.terms.forbidResell": "Revendre l'accès, extraire le service par un robot au-delà d'un usage humain normal, ou copier Micabo pour en faire un produit concurrent à partir de nos générations.",
        "legal.terms.forbidIllegal": "Déposer des contenus illégaux, haineux, ou qui portent atteinte à la vie privée d'autrui.",
        "legal.terms.availTitle": "Disponibilité",
        "legal.terms.availBody": "Nous faisons notre possible pour que les apps et le site restent joignables. Une maintenance, une panne d'un prestataire (hébergeur, modèle, boutique) ou une erreur de génération peut interrompre le service. Nous n'offrons pas de garantie de résultat scolaire, ni de disponibilité ininterrompue.",
        "legal.terms.liabilityTitle": "Responsabilité",
        "legal.terms.liabilityConsumer": "Si vous êtes un consommateur, vos droits légaux (garantie, médiation, clauses abusives) s'appliquent et ces conditions ne les écartent pas.",
        "legal.terms.liabilityLimit": "Au-delà, Micabo n'est pas responsable des notes obtenues, d'une fiche incomplète, d'un oubli le jour J, ou d'un dommage indirect (temps perdu, examen manqué). Notre responsabilité, si elle était retenue pour un manquement qui nous est imputable, est limitée au montant que vous nous avez versé au cours des douze derniers mois — sauf faute lourde, dol, ou atteinte à l'intégrité de la personne.",
        "legal.terms.minorsTitle": "Mineurs",
        "legal.terms.minorsBody": "Si vous avez moins de quinze ans, un titulaire de l'autorité parentale doit accepter ces conditions et surveiller l'usage. Le partage d'un cours avec des amis reste sous votre responsabilité, et sous la leur.",
        "legal.terms.lawTitle": "Droit applicable",
        "legal.terms.lawBody": "Ces conditions sont régies par le droit français. En cas de litige, et après une tentative de résolution écrite à [[contact]], les tribunaux français sont compétents — sous réserve des règles de protection du consommateur qui vous seraient plus favorables.",
        "legal.terms.changesTitle": "Modifications",
        "legal.terms.changesBody": "Nous pouvons mettre à jour ces conditions. La date en tête de page fait foi. Un changement qui touche au prix d'un abonnement en cours vous est annoncé avant le renouvellement.",
        "legal.terms.changesAlso": "La [[privacy]] décrit le traitement de vos données.",
        "articles.shared.navAria": "Pages",
        "articles.shared.nextTitle": "À lire ensuite",
        "articles.shared.ctaTitle": "Tape un sujet, regarde ce qu'il devient.",
        "articles.shared.ctaBody": "Sur le site comme sur iPhone, avec le même compte et les mêmes leçons.",
        "articles.method.metaTitle": "La méthode : répétition espacée et rappel actif, dans une leçon",
        "articles.method.metaDescription": "Relire un cours ne le fait pas retenir. Ce qu'on retrouve de mémoire tient, surtout si la question revient juste avant l'oubli. Comment une leçon Micabo applique le rappel actif et l'espacement, avec les vrais intervalles.",
        "articles.method.h1": "Relire ne suffit pas. Se souvenir, oui.",
        "articles.method.lead1": "Une page relue quatre fois donne une impression de maîtrise qui ne survit pas à la copie double. Ce qui progresse, c'est la reconnaissance : « oui, j'ai déjà vu ça ». Et la reconnaissance n'est pas ce qu'un examen demande.",
        "articles.method.lead2": "Ce qui tient, c'est ce qu'on a dû **retrouver de mémoire**, et ce qui revient **juste avant qu'on l'oublie**. Deux idées anciennes, mesurées depuis plus d'un siècle, et deux idées pénibles à appliquer à la main. C'est ce qu'une leçon Micabo fait à ta place.",
        "articles.method.activeTitle": "Le rappel actif : la question avant la réponse",
        "articles.method.active1": "Se tester est plus efficace que relire, même quand on se trompe. L'effort de récupération est ce qui renforce la trace : une réponse qu'on cherche pendant trois secondes vaut mieux qu'une réponse qu'on lit en une.",
        "articles.method.active2": "C'est pourquoi chaque thème d'une leçon finit par **une question**, et chaque palier par un checkpoint : tu ne passes pas à la suite sans avoir retrouvé ce que tu viens de lire. Et une question ratée ne disparaît pas, elle devient une flashcard.",
        "articles.method.spacingTitle": "L'espacement : revenir au dernier moment utile",
        "articles.method.spacing1": "Sans révision, ce qu'on retient d'un cours tombe à presque rien en un mois. Chaque rappel remet le compteur à cent, et la descente qui suit est **plus lente que la précédente**. Réviser au bon moment ne demande donc pas plus de temps : ça en demande moins, à mesure que la mémoire se stabilise.",
        "articles.method.spacing2": "L'intérêt n'est pas la forme de chaque courbe, c'est **l'endroit où elles se séparent** : la première révision. Ce que les flashcards d'une leçon automatisent, c'est le choix de cet instant, carte par carte.",
        "articles.method.lessonTitle": "La leçon d'abord, les flashcards ensuite",
        "articles.method.lesson1": "Une flashcard suppose qu'on a déjà compris. Se tester sur une notion qu'on n'a pas lue, c'est apprendre une réponse par cœur sans savoir de quoi elle parle. C'est pourquoi Mika écrit d'abord **les notes** de chaque thème : courtes, avec les mots-clés en évidence, et un encadré pour ce qu'il faut retenir.",
        "articles.method.lessonFigure": "Les notes d'un thème, telles que Mika les écrit : le mot-clé en couleur, la définition, **ce qu'il faut retenir** dans un encadré. Ce sont les mêmes blocs que dans l'app.",
        "articles.method.lesson2": "Puis viennent le quiz et les flashcards, tirés de ces notes et non du document brut. Tu lis, tu réponds, et seulement ensuite les cartes reviennent, au rythme de l'espacement.",
        "articles.method.plannerTitle": "Ce que Micabo calcule à chaque note",
        "articles.method.planner1": "Les flashcards sont planifiées en **SM-2**, la règle d'Anki dans ses réglages par défaut. Une carte neuve passe par des paliers courts, {steps}, avant de sortir en jours. Ensuite, chaque note multiplie l'intervalle par une facilité propre à la carte, qui part de {ease} et bouge selon tes réponses.",
        "articles.method.planner2": "Trois boutons : Encore, Bien, Facile. « Je sais / je ne sais pas » ne distingue pas la carte retrouvée avec peine de celle qui est venue seule, et c'est cet écart qui décide de la date suivante. Voici ce que les trois boutons annoncent sur une carte neuve :",
        "articles.method.buttonsCaption": "Les intervalles sont calculés par le planificateur de l'app, pas écrits à la main.",
        "articles.method.planner3": "L'intervalle est écrit sur le bouton **avant** qu'on appuie. Un planificateur qui décide dans son coin se fait vite désobéir : on note « facile » pour aller plus vite, la carte repart à trois semaines, et on la redécouvre le jour de l'épreuve.",
        "articles.method.stepMinutes": "{n} min",
        "articles.method.stepJoin": ", puis ",
        "articles.method.formatsTitle": "Cinq façons d'être interrogé sur les mêmes notes",
        "articles.method.formats1": "Le rappel actif ne se limite pas au recto verso. Sur un même thème, le quiz pose des QCM, du vrai ou faux, des textes à trou, des remises en ordre, des associations. Les questions viennent de tes notes, et chaque réponse dit tout de suite si c'est juste, et pourquoi.",
        "articles.method.formatsFigure": "Une question du quiz, la vraie : réponds, elle te corrige. **Les cinq formes sont tirées des mêmes notes**, du plus simple au plus exigeant.",
        "articles.method.limitsTitle": "Ce que la méthode ne fait pas",
        "articles.method.limits1": "La répétition espacée place les révisions. Elle ne comprend pas à ta place, elle ne rédige pas une dissertation, et elle ne rattrape pas un chapitre commencé la veille : il n'y a pas d'espacement possible sur une nuit.",
        "articles.method.limits2": "Elle ignore aussi les dates, par construction : SM-2 ne sait pas qu'un examen a lieu dans trois semaines. C'est exactement ce que le [[exam]] vient compléter.",
        "articles.method.examLink": "mode examen",
        "articles.method.note": "Une leçon s'ouvre librement à n'importe quelle étape : rien n'oblige à finir le chemin d'un trait. Ce que l'espacement demande, c'est seulement de revenir quand les cartes le disent.",
        "articles.exam.metaTitle": "Le mode examen : une date, des jours qui restent, un examen blanc",
        "articles.exam.metaDescription": "Tu donnes la date de ton examen, Micabo compte les jours sur chaque leçon au programme. L'examen blanc est chronométré, sans correction pendant l'épreuve, noté dans le barème de ton pays, et tes erreurs deviennent des flashcards.",
        "articles.exam.h1": "Tu donnes la date. Micabo compte les jours, et t'entraîne.",
        "articles.exam.lead1": "Apprendre une leçon et réussir une épreuve ne sont pas la même chose. Le jour J, on compose en temps limité, sans voir si l'on a juste, et l'on est noté sur un barème. Rien de tout ça n'arrive dans une révision ordinaire.",
        "articles.exam.lead2": "Le mode examen donne à tes leçons ce qui leur manque : **une date**, et une épreuve qui ressemble à la vraie. Tu poses le jour J, tu choisis les leçons au programme, et tu t'entraînes avec des examens blancs.",
        "articles.exam.dateTitle": "Une date, et les jours qui restent",
        "articles.exam.date1": "Un examen, c'est un nom, un jour, et les leçons qu'il couvre. À partir de là, chaque leçon au programme porte son compte à rebours, sur Home, dans la liste des leçons et dans l'onglet Examen : « J-12 » se lit avant d'avoir ouvert quoi que ce soit.",
        "articles.exam.date2": "Un examen peut couvrir plusieurs leçons, et une leçon peut être dans plusieurs examens. C'est toujours **le plus proche** qui s'affiche : il est la première contrainte. Passé le jour J, l'examen part dans les passés, et rien n'est à désactiver.",
        "articles.exam.mockTitle": "L'examen blanc : comme le vrai",
        "articles.exam.mock1": "Tu choisis la durée, {durations}, et les leçons. Mika écrit une copie neuve, du plus simple au plus exigeant, dans les cinq formes de question. Le chrono tourne, la réponse choisie se surligne sans verdict, tu reviens en arrière, tu changes d'avis. À zéro, la copie se rend seule.",
        "articles.exam.mockFigure": "La copie rendue : la note dans ton barème, **leçon par leçon**, et le corrigé de chaque question en dessous.",
        "articles.exam.mock2": "Le corrigé vient à la fin, question par question : ce que tu as répondu, la bonne réponse, et pourquoi. C'est là qu'on apprend, pas pendant l'épreuve, et c'est pour ça que l'épreuve ne corrige rien en cours de route.",
        "articles.exam.gradeTitle": "Notée dans ton barème",
        "articles.exam.grade1": "Une note sur vingt, une note sur dix, un pourcentage, une lettre, des paliers : le barème suit ton pays, posé dans ton profil. Un 14/20 français, un A américain et un 1,3 allemand ne se comparent pas, et un score universel ne voudrait rien dire nulle part.",
        "articles.exam.grade2": "Chaque leçon de la copie reçoit sa propre note. C'est elle qui dit où revenir : une leçon sous la moyenne la veille de l'épreuve est une leçon à rouvrir, et son chemin t'attend.",
        "articles.exam.cardsTitle": "Les erreurs deviennent des flashcards",
        "articles.exam.cards1": "Une question ratée à l'examen blanc ne reste pas sur la copie. D'un appui, elle rejoint les flashcards de sa leçon, due dès demain, et revient au rythme de l'espacement jusqu'à ce qu'elle tienne.",
        "articles.exam.cardsNote": "Rien ne t'oblige à les ajouter. Mais une erreur qu'on a vue une fois et jamais revue est exactement celle qu'on refait le jour J.",
        "articles.exam.limitsTitle": "Ce que le mode examen ne fait pas",
        "articles.exam.limits1": "Il ne fabrique pas du temps. Déclarer un examen pour demain sur une leçon qu'on n'a pas ouverte donne un compte à rebours honnête et une copie difficile, et Micabo les affiche tels quels plutôt que de rassurer.",
        "articles.exam.limits2": "Il ne remplace pas non plus [[method]] : ce sont les notes, les quiz et les flashcards qui font le travail, l'examen blanc ne fait que le mesurer. Si tu viens d'Anki, la [[anki]] dit précisément ce que ça change.",
        "articles.exam.methodLink": "la méthode",
        "articles.exam.ankiLink": "comparaison",
        "articles.exam.duration": "{minutes} min pour {count} questions",
        "articles.exam.durationJoin": ", ",
        "articles.anki.metaTitle": "Micabo ou Anki : ce qui change vraiment",
        "articles.anki.metaDescription": "Anki est ouvert, éprouvé et excellent. Micabo écrit la leçon à partir de ton support, ses notes, ses quiz et ses flashcards, et te note sur un examen blanc. Comparaison honnête, y compris là où Anki gagne.",
        "articles.anki.eyebrow": "Comparaison",
        "articles.anki.h1": "Micabo ou Anki : ce qui change vraiment",
        "articles.anki.lead1": "Anki est un très bon logiciel. Il est ouvert, il a vingt ans de recul et une communauté qui a tout documenté. Si tu t'en sers déjà et que ça te va, tu n'as aucune raison d'en changer.",
        "articles.anki.lead2": "La différence n'est pas dans la planification des flashcards : **c'est le même SM-2**. Elle est avant, dans la leçon qu'on n'a pas à écrire, et après, dans l'examen blanc et sa date.",
        "articles.anki.tableTitle": "Ligne par ligne",
        "articles.anki.tableLead": "Trois lignes vont à Anki, et elles sont écrites telles quelles.",
        "articles.anki.tableCaption": "Comparaison de Micabo et d'Anki, critère par critère.",
        "articles.anki.colCriterion": "Critère",
        "articles.anki.rowAlgo": "L'algorithme",
        "articles.anki.rowAlgoMicabo": "SM-2, avec les réglages par défaut d'Anki, trois boutons.",
        "articles.anki.rowAlgoAnki": "SM-2 historiquement, FSRS aujourd'hui, et les deux se règlent.",
        "articles.anki.rowWrite": "Écrire les cartes",
        "articles.anki.rowWriteMicabo": "Mika les écrit avec la leçon, thème par thème. Tu lis, tu réponds, elles reviennent.",
        "articles.anki.rowWriteAnki": "À toi. C'est là que passe l'essentiel du temps.",
        "articles.anki.rowLesson": "Comprendre avant de réviser",
        "articles.anki.rowLessonMicabo": "Des notes par thème, un quiz, un chemin d'étapes : la leçon avant les cartes.",
        "articles.anki.rowLessonAnki": "Rien : Anki suppose que tu as déjà compris.",
        "articles.anki.rowDate": "Une date d'examen",
        "articles.anki.rowDateMicabo": "Un compte à rebours sur chaque leçon, et des examens blancs notés dans ton barème.",
        "articles.anki.rowDateAnki": "Pas de notion de date. On avance le paquet à la main.",
        "articles.anki.rowQuestions": "Les façons d'être interrogé",
        "articles.anki.rowQuestionsMicabo": "QCM, vrai ou faux, texte à trou, remise en ordre, association, flashcards, examen blanc.",
        "articles.anki.rowQuestionsAnki": "Le recto verso, et les types de cartes qu'on construit soi-même.",
        "articles.anki.rowPlatforms": "Les plateformes",
        "articles.anki.rowPlatformsMicabo": "iPhone et navigateur, le même compte des deux côtés.",
        "articles.anki.rowPlatformsAnki": "Ordinateur, Android, iPhone, navigateur.",
        "articles.anki.rowDecks": "Les paquets tout faits",
        "articles.anki.rowDecksMicabo": "Aucun catalogue. Tes leçons, et une leçon de démonstration pour commencer.",
        "articles.anki.rowDecksAnki": "Des milliers de paquets publics, de qualité inégale.",
        "articles.anki.rowStart": "La mise en route",
        "articles.anki.rowStartMicabo": "Un sujet tapé, un chemin à suivre, une leçon finie le soir même.",
        "articles.anki.rowStartAnki": "Des réglages à comprendre avant la première carte.",
        "articles.anki.costTitle": "Ce qu'Anki coûte vraiment : du temps",
        "articles.anki.cost1": "Un paquet Anki utile pour un cours de fac, c'est deux à quatre heures de saisie par chapitre : découper, formuler une question par idée, ne pas empiler cinq éléments sur une carte. Ce travail est instructif, le nier serait malhonnête. Mais c'est le travail qui fait qu'on ouvre Anki en septembre et plus en novembre.",
        "articles.anki.costFigure": "Un sujet tapé, un PDF, une photo, un audio, une vidéo, un texte collé : **tout entre tel quel**. La saisie disparaît, la lecture et les questions restent.",
        "articles.anki.cost2": "Micabo prend cette étape. Le support devient une leçon : des notes par thème, un quiz, des flashcards. Tu lis, tu réponds, tu corriges ce qui ne va pas. Ça reste ton travail, mais il commence à la lecture au lieu de commencer à la page blanche.",
        "articles.anki.costNote": "Le revers est réel : une note générée peut être mal formulée ou tirée d'un scan mal lu. C'est pour ça que les notes viennent avant les cartes, et que Mika n'écrit pas un point dont le support ne parle pas. Une note qui se trompe ne ressemble pas à une erreur.",
        "articles.anki.dateTitle": "Ce qu'Anki ne fait pas : l'épreuve",
        "articles.anki.date1": "C'est la vraie différence de mécanique. Anki fait revenir des cartes, indéfiniment, sans savoir qu'il y a un partiel le 14 ni à quoi ressemble une copie en temps limité.",
        "articles.anki.date2": "Dans Micabo, tu poses la date, chaque leçon porte son compte à rebours, et tu passes des examens blancs chronométrés, notés dans ton barème, dont les erreurs reviennent en flashcards. [[exam]] détaille comment.",
        "articles.anki.examLink": "Le mode examen",
        "articles.anki.pickTitle": "Lequel prendre",
        "articles.anki.pickAnki": "**Reste sur Anki** si tu aimes régler ton planificateur, si tu veux FSRS, si tu es sur Android, ou si tu tiens à un outil ouvert dont tu possèdes les fichiers.",
        "articles.anki.pickMicabo": "**Essaie Micabo** si ce qui te bloque n'est pas la révision mais tout ce qui vient avant, comprendre et fabriquer les questions, ou si tes révisions sont organisées autour d'examens plutôt que d'un flux continu.",
        "articles.anki.pickBoth": "Et si tu hésites : [[method]] est la même dans les deux. C'est elle qui fait le travail, pas le logiciel qui la porte.",
        "articles.anki.methodLink": "la méthode",
    ]

