        "landing.metaTitle": "Micabo - Lerne schneller mit KI",
        "landing.siteTitle": "Micabo - Lerne schneller mit KI",
        "landing.metaDescription": "Tippe ein Thema oder lege ein PDF, ein Foto, eine Aufnahme, ein Video ab. Mika schreibt Notizen, Quiz und Karten, und du folgst dem Weg bis zum Abschlussquiz. Dann eine Probeprüfung, benotet wie die echte.",
        "landing.ogDescription": "Ein Thema wird zum Lektionsweg: Notizen, Quiz, Karten, Probeprüfung.",
        "landing.ogDescriptionShort": "Ein Thema wird zum Lektionsweg: Notizen, Quiz, Karten, Probeprüfung.",
        "landing.schemaDescription": "Micabo macht aus einem Thema oder Dokument eine Lektion: einen Weg aus Schritten mit Notizen, Quiz und Karten, dann Probeprüfungen, benotet nach dem System deines Landes.",
        "landing.manifestDescription": "Tippe ein Thema, lege eine Quelle ab. Mika schreibt die Lektion, du folgst dem Weg.",
        "landing.howEyebrow": "So funktioniert es",
        "landing.howTitle": "Von deinem Kurs zu deiner Lektion, in drei Schritten.",
        "landing.howNote": "Nichts vorbereiten, nichts abschreiben. Du lädst hoch, was du hast, Mika macht den Rest.",
        "landing.stepEyebrow": "Schritt {n}",
        "landing.step1Title": "Du lädst deinen Kurs hoch.",
        "landing.step1Body": "Ein PDF, ein Word-Dokument, ein Foto der Tafel, ein YouTube-Video, eine Aufnahme oder zwei getippte Wörter: bis zu fünf Unterlagen auf einmal.",
        "landing.step2Title": "Mika schreibt die Lektion.",
        "landing.step2Body": "Ein Plan in Themen, dann für jedes klare Notizen mit ihren Schlüsselbegriffen, ein Quiz und Karteikarten. Das erste Thema ist fertig, während die anderen noch entstehen.",
        "landing.step3Title": "Du folgst dem Weg.",
        "landing.step3Body": "Ein Schritt nach dem anderen, bis zum Abschlussquiz. Eine falsche Antwort wird zur Karteikarte für morgen, und am Ende wartet die Probeprüfung.",
        "landing.methodMore": "Die Methode im Detail",
        "landing.examMore": "Wie die Prüfung vorbereitet wird",
        "landing.questionsEyebrow": "Fragen",
        "landing.questionsTitle": "Was man uns fragt.",
        "landing.questionsNote": "Die, die man sich vor der ersten Lektion stellt.",
        "landing.questionsMore": "Micabo oder Anki: der Vergleich",
        "landing.faq1q": "Sind meine Lektionen privat?",
        "landing.faq1a": "Ja. Deine Lektionen stehen in keinem Katalog: nur du siehst sie. Die Trennung sitzt in der Datenbank, jede Anfrage wird mit deiner Identität geprüft, es gibt also keine Anfrage, die fremde Lektionen lesen könnte.",
        "landing.faq2q": "Erfindet Mika Dinge?",
        "landing.faq2a": "Das Risiko nehmen wir am ernstesten, weil eine falsche Notiz nicht wie ein Fehler aussieht. Aus einer Quelle schreibt Mika nur, was die Quelle sagt, und wo der Text nichts entscheidet, taucht der zweifelhafte Punkt nicht auf. Aus einem getippten Thema sind die Notizen die eines Referenzkurses, und das Quiz lässt dich sie prüfen.",
        "landing.faq3q": "Geht das in anderen Sprachen? Anderen Schulsystemen?",
        "landing.faq3a": "Ja. Dein Land bestimmt das Notensystem und die Sprache der Lektionen. Die Seite selbst gibt es in 26 Sprachen: Sprache oben auf der Seite, im Ablauf oder im Profil wechseln.",
        "landing.faq4q": "Wie lange dauert eine Lektion?",
        "landing.faq4a": "Das Intro sagt es: oft zehn bis fünfundzwanzig Minuten bis zum Abschlussquiz, mehr bei einem großen Kapitel. Du kannst bei jedem Schritt aufhören, der Weg wartet dort auf dich.",
        "landing.faq5q": "Und wenn ich schon Anki nutze?",
        "landing.faq5a": "Micabos Karten kommen nach Ankis Regel zurück: drei Knöpfe, dieselben Intervalle. Was Micabo hinzufügt, macht Anki nicht: die Lektion mit Notizen und Quiz aus deiner Quelle schreiben, und dich in einer Probeprüfung benoten.",
        "landing.closingTitle": "Deine nächste Prüfung hat ein Datum. Deine erste Lektion beginnt jetzt.",
