        "copy.heldBackNew": "{count, plural, one {# neue Karte für später — dein Tempo für heute ist erreicht.} other {# neue Karten für später — dein Tempo für heute ist erreicht.}}",
        "copy.alreadySubscribed": "Du hast schon ein Abo.",
        "legal.eyebrow": "Micabo · iPhone, Android und Website",
        "legal.updated": "Zuletzt aktualisiert: {date}.",
        "legal.updatedDate": "23. Oktober 2026",
        "legal.privacy.metaTitle": "Datenschutz",
        "legal.privacy.metaDescription": "Was Micabo von Ihnen behält, auf dem iPhone, auf Android und auf der Website, und was Sie damit tun können.",
        "legal.privacy.heading": "Datenschutzrichtlinie",
        "legal.privacy.linkLabel": "Datenschutzrichtlinie",
        "legal.privacy.intro1": "Diese Richtlinie beschreibt die Daten, die Micabo verarbeitet, wenn Sie die Website [[site]], die iPhone-App (Kennung {bundle}, im App Store) oder die Android-App (Paket {package}, bei Google Play) nutzen. Die drei Clients teilen dasselbe Konto und dieselbe Datenbank. Sie gilt auch, wenn Sie noch kein Konto haben und die Website nur ansehen.",
        "legal.privacy.intro2": "Verantwortlich für die Verarbeitung ist {editor}. Für Fragen, Berichtigungen oder Löschungen: [[contact]].",
        "legal.privacy.whatTitle": "Was Micabo ist",
        "legal.privacy.whatBody": "Micabo verwandelt einen Kurs (PDF, Foto, Dokument, Video) in ein Merkblatt und in Karteikarten und lässt sie wiederkehren, bevor Sie sie vergessen. Ein Prüfungsmodus verdichtet die Wiederholungen vor einem Termin. Sie können einen Kurs mit Freunden teilen oder für sich behalten.",
        "legal.privacy.dataTitle": "Welche Daten wir verarbeiten",
        "legal.privacy.dataAccount": "**Das Konto.** E-Mail-Adresse, Kennungen von Apple oder Google, wenn Sie diese Anmeldung wählen, und ein Benutzername. Wir speichern Ihr Passwort nicht: die E-Mail-Anmeldung erfolgt über einen Link, nicht über ein Geheimnis, das wir behalten würden.",
        "legal.privacy.dataSchool": "**Der Bildungsweg.** Studienland, Stufe, Fächer, Einrichtung, wenn Sie sie angeben. Damit schreiben wir das Merkblatt in der richtigen Sprache und im richtigen System und zeigen Ihnen Kommilitonen derselben Einrichtung, wenn ein Kurs geteilt wird.",
        "legal.privacy.dataCourses": "**Ihre Kurse.** Die Dateien oder Links, die Sie ablegen, der daraus gelesene Text, die erzeugten Merkblätter und Karten, Schema-Bilder, Prüfungen (Name, Datum, Zielnote) und der Wiederholungsverlauf (wann eine Karte wiederkehrt, wie Sie sie bewertet haben).",
        "legal.privacy.dataFriends": "**Die Freunde.** Freundschaftsanfragen, Ihre Freundesliste und die Sichtbarkeit, die Sie jedem Kurs beim Import geben: nur Sie, Ihre Freunde oder die Kommilitonen Ihrer Einrichtung. Es gibt keinen öffentlichen Katalog, in dem ein Unbekannter auf Ihre Merkblätter stoßen würde.",
        "legal.privacy.dataSubscription": "**Das Abo.** Der Stand Ihres Pro-Zugangs (aktiv, Testphase, gekündigt), nicht Ihre Kartennummer. Die Zahlung nimmt Apple auf dem iPhone entgegen (App Store), Google auf Android (Google Play), Stripe auf der Website. RevenueCat hält das Recht, damit iPhone, Android und Browser übereinstimmen.",
        "legal.privacy.dataWaitlist": "**Die Warteliste.** Wenn Sie Ihre Adresse hinterlassen, bevor Sie ein Konto haben, behalten wir sie, um Sie über die Öffnung zu informieren, zusammen mit der Seite, von der Sie kommen. Sie ist an kein Konto gebunden und in der App nicht sichtbar.",
        "legal.privacy.dataFeedback": "**Die Rückmeldungen.** Wenn Sie einen Fehler oder eine Idee aus der App senden, behalten wir die Nachricht, den Typ (Fehler oder Idee) und die Verbindung zu Ihrem Konto, um zu antworten. Sie bleiben 24 Monate und werden dann gelöscht. Sie dienen nicht dazu, Sie zu profilieren.",
        "legal.privacy.dataUsage": "**Die Nutzung der Generierungen.** Ein Zähler pro Tag und Funktion (Merkblatt, Karten, Erklärung), ohne den Inhalt des Kurses. Er dient dazu, Missbrauch zu begrenzen, nicht Sie zu profilieren.",
        "legal.privacy.dataDirectory": "**Das Verzeichnis.** Ihr Benutzername und, wenn Sie es angegeben haben, Ihre Einrichtung. Das sieht ein Freund oder ein Kommilitone, nicht Ihre E-Mail und nicht Ihre Einstellungen.",
        "legal.privacy.dataDevice": "**Was auf dem Gerät bleibt.** Auf dem iPhone und auf Android können manche Teile (Okklusionsbilder, Audio einer Karte) das Telefon nie verlassen. Die Antworten des Begrüßungswegs bleiben zuerst auf dem Gerät und werden erst nach der Kontoeröffnung in die Datenbank geschrieben.",
        "legal.privacy.dataNoSell": "Wir verkaufen Ihre Daten nicht. Wir zeigen keine Werbung. Wir trainieren kein Sprachmodell auf Ihren Kursen, außer wenn eine ausdrückliche Einstellung das eines Tages anbietet — und diese Einstellung gibt es heute nicht.",
        "legal.privacy.whyTitle": "Warum wir sie verarbeiten",
        "legal.privacy.whyLead": "Die Rechtsgrundlagen im Sinne der DSGVO:",
        "legal.privacy.whyContract": "**Die Vertragserfüllung** — das Konto anlegen, einen Kurs importieren, Merkblatt und Karten schreiben, sie wiederholen, die iPhone- und Android-Apps und die Website synchronisieren, das Abo verwalten.",
        "legal.privacy.whyLegitimate": "**Das berechtigte Interesse** — den Dienst sichern, Missbrauch verhindern, eine Störung diagnostizieren, die Reichweite der Website in aggregierter Form messen und die Rückmeldungen lesen, die Sie uns senden. Dieses Interesse geht nicht vor Ihrem: die Trennung liegt in der Datenbank, nicht nur in der Anwendung.",
        "legal.privacy.whyLegal": "**Die gesetzliche Pflicht** — das aufzubewahren, was Abrechnung oder Buchhaltung verlangen, für die vorgeschriebene Zeit.",
        "legal.privacy.whyConsent": "**Die Einwilligung** — wenn Sie einen Kurs teilen, die Kamera öffnen oder sich mit Apple oder Google anmelden.",
        "legal.privacy.accessTitle": "Wer Zugriff hat",
        "legal.privacy.accessBody": "Ihre Kurse sind nur für Sie lesbar, außer Sie haben sie geteilt. Jede Anfrage an die Datenbank wird mit Ihrer Identität geprüft: es gibt keine Anfrage, die die Kurse eines anderen verlangen kann. Die Rückmeldungen, die Sie senden, liest das Team unter [[contact]]. Niemand sonst hat von der Anwendung aus Zugriff.",
        "legal.privacy.accessLead": "Dienstleister sehen einen Teil der Daten, ausschließlich um den Dienst zu erbringen:",
        "legal.privacy.accessSupabase": "**Supabase** (Europäische Union, Region Stockholm) — Konto, Datenbank, Dateien.",
        "legal.privacy.accessVercel": "**Vercel** — Hosting der Website, technische Protokolle (IP-Adresse, URL) und Reichweitenmessung: die Zahl der Seitenaufrufe, die Seite, von der Sie kommen, das Land und die Geräteart, ohne Cookie und ohne Kennung, die Ihnen folgt. Die Verarbeitung kann außerhalb der Europäischen Union stattfinden, unter den Standardvertragsklauseln des Anbieters.",
        "legal.privacy.accessApple": "**Apple und Google** — wenn Sie sich über sie anmelden oder im App Store (Apple) oder bei Google Play (Google) zahlen.",
        "legal.privacy.accessStripe": "**Stripe** — Zahlung auf der Website.",
        "legal.privacy.accessRevenuecat": "**RevenueCat** — Abo-Stand, geteilt zwischen iPhone, Android und Website.",
        "legal.privacy.accessFal": "**fal.ai und die Modelle, die es aufruft** (heute Sprachmodelle, insbesondere von Google) — der Text oder das Bild Ihres Kurses, für die Zeit, das Merkblatt oder die Karten zu schreiben. Sie dürfen sie für nichts anderes als diese Generierung verwenden.",
        "legal.privacy.accessYoutube": "**YouTube / Google** — wenn Sie ein Video importieren, lesen wir dessen Metadaten und Untertitel.",
        "legal.privacy.accessTransfer": "Einige dieser Dienstleister sind außerhalb der Europäischen Union niedergelassen. Die Übermittlung erfolgt dann nur, um den Dienst zu erbringen, und stützt sich auf die von der DSGVO vorgesehenen Garantien (Angemessenheitsbeschluss oder Standardvertragsklauseln des Anbieters).",
        "legal.privacy.cookiesTitle": "Cookies und Tracker",
        "legal.privacy.cookiesWeb": "Die Website setzt die für die Sitzung nötigen Cookies (Sie von einer Seite zur nächsten wiedererkennen, sobald Sie angemeldet sind) und ein Cookie für die Oberflächensprache (`micabo.ui_locale`), ein Jahr gültig, das die Sprache merkt, die Sie für die Oberfläche gewählt haben. Nach der Anmeldung merkt ein Cookie `micabo.learner`, ein Jahr gültig, in diesem Browser Ihre genaue Stufe und die beim Begrüßungsweg angegebenen Noten: er dient nur dazu, Ihre Lektionen auf dem richtigen Niveau zu schreiben. Wir setzen kein Audience-Cookie, keine Werbung und kein standortübergreifendes Tracking. Die Website zählt ihre Besuche durchaus, schreibt dafür aber nichts auf Ihr Gerät: die Messung behält einen Seitenaufruf, dessen Herkunft, ein Land, eine Geräteart — und nichts, womit man Sie von einem Besuch zum nächsten oder auf einer anderen Website wiedererkennen könnte. Deshalb gibt es kein Einwilligungsbanner: auf dieser Seite gibt es nichts abzulehnen.",
        "legal.privacy.cookiesIos": "Die iPhone- und Android-Apps verwenden keine Cookies. Sie bewahren ein Sitzungstoken im geschützten Speicher des Geräts: im Schlüsselbund auf dem iPhone, im privaten Speicher der App auf Android.",
        "legal.privacy.retentionTitle": "Wie lange wir sie behalten",
        "legal.privacy.retentionWhile": "Solange das Konto besteht. Rückmeldungen gehen spätestens nach 24 Monaten. Wenn Sie es löschen, unter Einstellungen auf der Website oder in den iPhone- und Android-Apps oder indem Sie uns schreiben, löschen wir das Profil, die Kurse (einschließlich des gelesenen Texts), die Merkblätter, die Karten, den Verlauf, die Prüfungen, die Freundschaften, die Nutzungszähler, die Rückmeldungen und die Adresse, die Sie gegebenenfalls auf der Warteliste hinterlassen haben.",
        "legal.privacy.retentionShared": "Ein Kurs, den Sie geteilt haben, verschwindet für Ihre Freunde, wenn Sie ihn löschen. Ein Freund, der Ihre Karten schon wiederholt hat, behält seinen eigenen Verlauf, nicht Ihr Dokument.",
        "legal.privacy.retentionAfter": "Nach der Löschung bleibt bei Dienstleistern, was das Gesetz oder ihr Vertrag verlangt: Rechnungen von Stripe, Apple oder Google, RevenueCat-Abo-Kennung, technische Protokolle (Vercel, Supabase) einige Wochen. fal.ai erhält den Text für die Zeit, das Merkblatt zu schreiben; wir verlangen nicht, dass es ihn behält.",
        "legal.privacy.rightsTitle": "Ihre Rechte",
        "legal.privacy.rightsBody": "Sie können auf Ihre Daten zugreifen, sie berichtigen, sie exportieren, einer Verarbeitung widersprechen oder die Löschung verlangen. Eine Kopie herunterladen: Einstellungen → „Meine Daten herunterladen“. Das Konto löschen: Einstellungen → „Konto löschen“, auf der Website oder in den iPhone- und Android-Apps. Sie können auch an [[contact]] schreiben. Wir antworten innerhalb eines Monats.",
        "legal.privacy.rightsCnil": "Sie können auch eine Beschwerde bei der CNIL einreichen (cnil.fr).",
        "legal.privacy.minorsTitle": "Minderjährige",
        "legal.privacy.minorsBody": "Micabo richtet sich an Studierende, auch in der Oberstufe. Wir fragen nicht nach dem Geburtsdatum. Wenn Sie unter fünfzehn sind, muss die Nutzung mit Zustimmung eines Sorgeberechtigten erfolgen. Wir verwenden die Daten eines Minderjährigen nicht für Werbung und nicht für ein kommerzielles Profiling.",
        "legal.privacy.iosTitle": "Die iPhone- und Android-Apps, zusätzlich zur Website",
        "legal.privacy.iosBody": "Die Apps können den Zugriff auf Ihre Fotos, Ihre Dateien oder die Kamera verlangen, um einen Kurs zu importieren. Das ist nicht Pflicht: die Website nimmt eine abgelegte Datei an. Benachrichtigungen, wenn Sie sie erlauben, dienen nur dazu, Sie an eine Wiederholung zu erinnern. Dasselbe Konto öffnet die iPhone-App, die Android-App und die Website.",
        "legal.privacy.changesTitle": "Änderungen",
        "legal.privacy.changesBody": "Ändert sich diese Richtlinie wesentlich, aktualisieren wir das Datum am Seitenanfang. Die weitere Nutzung nach diesem Datum gilt für die neue Fassung, außer das Gesetz verlangt eine gesonderte Zustimmung.",
        "legal.privacy.changesAlso": "Die [[terms]] ergänzen diesen Text.",
        "legal.terms.metaTitle": "Nutzungsbedingungen",
        "legal.terms.metaDescription": "Die Regeln des Micabo-Dienstes für iPhone, Android und Website: Konto, Kurse, Abo, Haftung.",
        "legal.terms.heading": "Nutzungsbedingungen",
        "legal.terms.linkLabel": "Nutzungsbedingungen",
        "legal.terms.intro1": "Diese Bedingungen regeln die Nutzung von Micabo — der Website [[site]], der iPhone-App ({bundle}, im App Store) und der Android-App ({package}, bei Google Play). Indem Sie ein Konto anlegen oder den Dienst nutzen, akzeptieren Sie sie. Wenn Sie nicht einverstanden sind, legen Sie kein Konto an.",
        "legal.terms.intro2": "Herausgeber ist {editor}. Kontakt: [[contact]].",
        "legal.terms.serviceTitle": "Der Dienst",
        "legal.terms.serviceBody": "Micabo liest ein Kursdokument, das Sie ablegen, und schreibt daraus ein Merkblatt und Karteikarten. Es lässt sie nach einer verteilten Wiederholung zurückkehren (dieselbe SM-2-Regel auf dem iPhone, auf Android und auf der Website). Sie können das Datum einer Prüfung setzen: der Wiederholungsplan verdichtet sich dann auf diesen Tag. Ein und dasselbe Konto öffnet alle drei Clients.",
        "legal.terms.servicePro": "Ein Teil des Dienstes ist ohne Abo zugänglich. Der Pro-Zugang (Kurse und Karten über die kostenlose Grenze hinaus, gemäß dem Angebot zum Zeitpunkt des Kaufs) ist kostenpflichtig.",
        "legal.terms.accountTitle": "Das Konto",
        "legal.terms.accountBody": "Sie können sich mit Apple, Google oder einem per E-Mail gesendeten Link anmelden. Sie sind für den Zugang zu Ihrem Postfach und zu diesen Drittkonten verantwortlich. Ein Konto pro Person.",
        "legal.terms.accountDelete": "Sie können das Konto unter Einstellungen löschen, auf der Website oder in den iPhone- und Android-Apps. Das löscht Ihre Kurse, Ihre Karten und Ihren Verlauf. Das Löschen des Kontos kündigt kein Abo, das im App Store oder bei Google Play abgeschlossen wurde: Kündigen Sie es im Store. Bereits von Apple, Google oder Stripe eingenommene Käufe bleiben deren Erstattungsregeln unterworfen.",
        "legal.terms.coursesTitle": "Ihre Kurse",
        "legal.terms.coursesOwn": "Sie behalten das Eigentum an dem, was Sie ablegen. Sie geben uns nur das begrenzte und widerrufliche Recht, es zu lesen, zu speichern und in ein Merkblatt und in Karten zu verwandeln, um Ihnen den Dienst zu erbringen — einschließlich der Weitergabe an ein Sprachmodell für die Dauer der Generierung.",
        "legal.terms.coursesRights": "Sie legen nur Dokumente ab, die Sie nutzen dürfen. Ein Skript Ihres Dozenten, Ihre Notizen, ein Video, dessen Import erlaubt ist: ja. Ein ganzes abgeschriebenes Werk, die Arbeit eines anderen, ein rechtswidriger Inhalt: nein. Wir können einen Kurs entfernen oder ein Konto schließen, das diese Regel bricht.",
        "legal.terms.coursesShare": "Die Sichtbarkeit wird beim Import festgelegt. Ein privater Kurs bleibt bei Ihnen. Ein geteilter Kurs ist nur für die Personen sichtbar, die Sie gewählt haben (Freunde oder Kommilitonen der Einrichtung). Das ist keine für alle offene Bibliothek.",
        "legal.terms.notTitle": "Was Micabo nicht ist",
        "legal.terms.notBody": "Merkblatt und Karten werden automatisch erzeugt. Sie können sich irren, eine Stelle auslassen oder einen Scan falsch lesen. Micabo ist kein Lehrer und keine Notengarantie. Sie bleiben verantwortlich für das, was Sie lernen und am Prüfungstag abgeben.",
        "legal.terms.notInvent": "Wir bemühen uns, keine Definition zu erfinden, wenn das Dokument sie nicht trägt. Das macht das Ergebnis nicht unfehlbar.",
        "legal.terms.subTitle": "Das Abo",
        "legal.terms.subPrices": "Preise, Laufzeit und eine etwaige Probezeit sind die vor der Zahlung angezeigten. Sie können sich für neue Käufe ändern; ein laufendes Abo behält seine Bedingungen bis zur Verlängerung.",
        "legal.terms.subIos": "**Auf dem iPhone** läuft die Zahlung über den App Store: Kündigung, Verlängerung und Erstattungen folgen den Regeln von Apple, und Sie verwalten oder kündigen das Abo in den Einstellungen Ihres Apple-Kontos (Einstellungen → Ihr Name → Abonnements). **Auf Android** läuft die Zahlung über Google Play: Kündigung, Verlängerung und Erstattungen folgen den Regeln von Google Play, und Sie verwalten oder kündigen das Abo in der Google-Play-App (Zahlungen und Abos → Abos).",
        "legal.terms.subWeb": "**Auf der Website** läuft die Zahlung über Stripe. Die Kündigung erfolgt über den im Profil angegebenen Abrechnungsbereich oder indem Sie uns schreiben. Eine Probezeit, wenn sie angeboten wird, wird nur dann zur Zahlung, wenn Sie sie auslaufen lassen.",
        "legal.terms.subBoth": "Der auf einer Seite gekaufte Pro-Zugang gilt auf den anderen: dasselbe Konto ist Pro auf dem iPhone, auf Android und auf der Website. Ein Zahlungsvorfall kann eine Schonfrist öffnen; wir schließen den Zugang nicht in der ersten Stunde.",
        "legal.terms.forbidTitle": "Was Sie nicht tun",
        "legal.terms.forbidHarm": "Den Dienst nutzen, um jemandem zu schaden, zu belästigen oder auf eine Weise zu schummeln, die die Ordnung Ihrer Einrichtung verletzt.",
        "legal.terms.forbidAccess": "Versuchen, auf die Kurse eines anderen Kontos zuzugreifen, die Trennung zu umgehen oder den Dienst absichtlich zu überlasten.",
        "legal.terms.forbidResell": "Den Zugang weiterverkaufen, den Dienst über einen Roboter hinaus über normalen menschlichen Gebrauch auslesen oder Micabo kopieren, um aus unseren Generierungen ein Konkurrenzprodukt zu machen.",
        "legal.terms.forbidIllegal": "Rechtswidrige, hasserfüllte Inhalte ablegen oder solche, die die Privatsphäre anderer verletzen.",
        "legal.terms.availTitle": "Verfügbarkeit",
        "legal.terms.availBody": "Wir tun unser Möglichstes, damit die Apps und die Website erreichbar bleiben. Eine Wartung, der Ausfall eines Dienstleisters (Hoster, Modell, Store) oder ein Generierungsfehler kann den Dienst unterbrechen. Wir bieten keine Garantie für schulische Ergebnisse und keine ununterbrochene Verfügbarkeit.",
        "legal.terms.liabilityTitle": "Haftung",
        "legal.terms.liabilityConsumer": "Wenn Sie Verbraucher sind, gelten Ihre gesetzlichen Rechte (Gewährleistung, Mediation, missbräuchliche Klauseln), und diese Bedingungen schließen sie nicht aus.",
        "legal.terms.liabilityLimit": "Darüber hinaus haftet Micabo nicht für erzielte Noten, ein unvollständiges Merkblatt, ein Vergessen am Prüfungstag oder einen indirekten Schaden (verlorene Zeit, verpasste Prüfung). Unsere Haftung, wenn sie für eine uns zurechenbare Pflichtverletzung festgestellt würde, ist auf den Betrag begrenzt, den Sie uns in den letzten zwölf Monaten gezahlt haben — außer bei grober Fahrlässigkeit, Vorsatz oder einer Verletzung der körperlichen Unversehrtheit.",
        "legal.terms.minorsTitle": "Minderjährige",
        "legal.terms.minorsBody": "Wenn Sie unter fünfzehn sind, muss ein Sorgeberechtigter diese Bedingungen akzeptieren und die Nutzung beaufsichtigen. Das Teilen eines Kurses mit Freunden bleibt in Ihrer Verantwortung und in der ihren.",
        "legal.terms.lawTitle": "Anwendbares Recht",
        "legal.terms.lawBody": "Diese Bedingungen unterliegen französischem Recht. Im Streitfall und nach einem schriftlichen Lösungsversuch an [[contact]] sind die französischen Gerichte zuständig — vorbehaltlich der Verbraucherschutzregeln, die für Sie günstiger wären.",
        "legal.terms.changesTitle": "Änderungen",
        "legal.terms.changesBody": "Wir können diese Bedingungen aktualisieren. Das Datum am Seitenanfang gilt. Eine Änderung, die den Preis eines laufenden Abos betrifft, wird Ihnen vor der Verlängerung mitgeteilt.",
        "legal.terms.changesAlso": "Die [[privacy]] beschreibt die Verarbeitung Ihrer Daten.",
        "articles.shared.navAria": "Seiten",
        "articles.shared.nextTitle": "Als Nächstes lesen",
        "articles.shared.ctaTitle": "Tippe ein Thema, sieh, was daraus wird.",
        "articles.shared.ctaBody": "Auf der Seite wie auf dem iPhone, mit demselben Konto und denselben Lektionen.",
        "articles.method.metaTitle": "Die Methode: verteiltes Wiederholen und aktives Abrufen, in einer Lektion",
        "articles.method.metaDescription": "Einen Kurs nachzulesen lässt ihn nicht im Kopf bleiben. Was man aus dem Gedächtnis holt, bleibt, besonders wenn die Frage kurz vor dem Vergessen zurückkommt. Wie eine Micabo-Lektion aktives Abrufen und Abstände anwendet, mit echten Intervallen.",
        "articles.method.h1": "Nachlesen reicht nicht. Erinnern schon.",
        "articles.method.lead1": "Eine viermal gelesene Seite gibt ein Gefühl von Beherrschung, das den Prüfungsbogen nicht überlebt. Was wächst, ist das Wiedererkennen: „ja, das habe ich gesehen“. Und Wiedererkennen ist nicht, was eine Prüfung verlangt.",
        "articles.method.lead2": "Was bleibt, ist, was man **aus dem Gedächtnis holen** musste, und was **kurz vor dem Vergessen** zurückkommt. Zwei alte Ideen, seit über einem Jahrhundert gemessen, und zwei Ideen, die von Hand mühsam sind. Genau das macht eine Micabo-Lektion für dich.",
        "articles.method.activeTitle": "Aktives Abrufen: die Frage vor der Antwort",
        "articles.method.active1": "Sich zu testen wirkt besser als nachzulesen, selbst wenn man sich irrt. Die Anstrengung des Abrufens stärkt die Spur: eine drei Sekunden gesuchte Antwort ist mehr wert als eine in einer gelesene.",
        "articles.method.active2": "Darum endet jedes Thema einer Lektion mit **einer Frage** und jede Stufe mit einem Checkpoint: du gehst nicht weiter, ohne das Gelesene abgerufen zu haben. Und eine falsche Frage verschwindet nicht, sie wird zur Karte.",
        "articles.method.spacingTitle": "Abstände: im letzten nützlichen Moment zurückkommen",
        "articles.method.spacing1": "Ohne Wiederholung fällt, was man von einem Kurs behält, in einem Monat auf fast nichts. Jedes Abrufen setzt den Zähler auf hundert, und der folgende Abfall ist **langsamer als der vorige**. Zum richtigen Zeitpunkt zu wiederholen kostet nicht mehr Zeit: es kostet weniger, je stabiler das Gedächtnis wird.",
        "articles.method.spacing2": "Interessant ist nicht die Form jeder Kurve, sondern **wo sie sich trennen**: die erste Wiederholung. Was die Karten einer Lektion automatisieren, ist die Wahl dieses Moments, Karte für Karte.",
        "articles.method.lessonTitle": "Erst die Lektion, dann die Karten",
        "articles.method.lesson1": "Eine Karte setzt voraus, dass man verstanden hat. Sich an einem ungelesenen Begriff zu testen heißt, eine Antwort auswendig zu lernen, ohne zu wissen, worum es geht. Darum schreibt Mika zuerst **die Notizen** jedes Themas: kurz, mit hervorgehobenen Schlüsselwörtern und einem Kasten für das, was zu behalten ist.",
        "articles.method.lessonFigure": "Die Notizen eines Themas, wie Mika sie schreibt: das Schlüsselwort in Farbe, die Definition, **was zu behalten ist** im Kasten. Dieselben Bausteine wie in der App.",
        "articles.method.lesson2": "Dann kommen Quiz und Karten, aus diesen Notizen und nicht aus dem Rohdokument. Du liest, du antwortest, und erst dann kommen die Karten zurück, im Rhythmus der Abstände.",
        "articles.method.plannerTitle": "Was Micabo bei jeder Bewertung berechnet",
        "articles.method.planner1": "Karten werden mit **SM-2** geplant, Ankis Regel in den Standardeinstellungen. Eine neue Karte durchläuft kurze Stufen, {steps}, bevor sie in Tage übergeht. Danach multipliziert jede Bewertung das Intervall mit einer kartenspezifischen Leichtigkeit, die bei {ease} beginnt und sich mit deinen Antworten bewegt.",
        "articles.method.planner2": "Drei Knöpfe: Nochmal, Gut, Leicht. „Ich weiß es / ich weiß es nicht“ unterscheidet die mühsam gefundene Karte nicht von der, die von selbst kam, und genau dieser Abstand entscheidet über das nächste Datum. Das kündigen die drei Knöpfe bei einer neuen Karte an:",
        "articles.method.buttonsCaption": "Die Intervalle berechnet der Planer der App, sie sind nicht von Hand geschrieben.",
        "articles.method.planner3": "Das Intervall steht auf dem Knopf, **bevor** man drückt. Einem Planer, der für sich entscheidet, gehorcht man bald nicht mehr: man drückt „leicht“, um schneller zu sein, die Karte geht für drei Wochen weg, und man entdeckt sie am Prüfungstag wieder.",
        "articles.method.stepMinutes": "{n} Min",
        "articles.method.stepJoin": ", dann ",
        "articles.method.formatsTitle": "Fünf Arten, zu denselben Notizen befragt zu werden",
        "articles.method.formats1": "Aktives Abrufen beschränkt sich nicht auf Vorder- und Rückseite. Zu einem Thema stellt das Quiz Multiple Choice, Wahr oder Falsch, Lückentexte, Reihenfolgen, Zuordnungen. Die Fragen kommen aus deinen Notizen, und jede Antwort sagt sofort, ob sie stimmt, und warum.",
        "articles.method.formatsFigure": "Eine Quizfrage, die echte: antworte, sie korrigiert dich. **Die fünf Formen kommen aus denselben Notizen**, von der einfachsten zur anspruchsvollsten.",
        "articles.method.limitsTitle": "Was die Methode nicht tut",
        "articles.method.limits1": "Verteiltes Wiederholen platziert Wiederholungen. Es versteht nicht für dich, es schreibt keinen Aufsatz, und es holt kein am Vorabend begonnenes Kapitel auf: über eine Nacht gibt es keinen Abstand.",
        "articles.method.limits2": "Es ignoriert auch Daten, von Natur aus: SM-2 weiß nicht, dass in drei Wochen eine Prüfung ist. Genau das ergänzt der [[exam]].",
        "articles.method.examLink": "Prüfungsmodus",
        "articles.method.note": "Eine Lektion öffnet sich frei an jedem Schritt: nichts zwingt, den Weg in einem Zug zu beenden. Die Abstände verlangen nur, dass du zurückkommst, wenn die Karten es sagen.",
        "articles.exam.metaTitle": "Der Prüfungsmodus: ein Datum, verbleibende Tage, eine Probeprüfung",
        "articles.exam.metaDescription": "Gib dein Prüfungsdatum, Micabo zählt die Tage auf jeder Lektion dazu. Die Probeprüfung läuft mit Zeit, ohne Korrektur währenddessen, benotet nach dem System deines Landes, und deine Fehler werden zu Karten.",
        "articles.exam.h1": "Du gibst das Datum. Micabo zählt die Tage und trainiert dich.",
        "articles.exam.lead1": "Eine Lektion zu lernen und eine Prüfung zu bestehen ist nicht dasselbe. Am Tag selbst schreibt man gegen die Zeit, ohne zu sehen, ob es stimmt, und wird nach einem System benotet. Nichts davon passiert beim gewöhnlichen Wiederholen.",
        "articles.exam.lead2": "Der Prüfungsmodus gibt deinen Lektionen, was ihnen fehlt: **ein Datum** und eine Prüfung, die der echten gleicht. Du setzt den Tag, wählst die Lektionen dazu und trainierst mit Probeprüfungen.",
        "articles.exam.dateTitle": "Ein Datum, und die verbleibenden Tage",
        "articles.exam.date1": "Eine Prüfung ist ein Name, ein Tag und die Lektionen, die sie umfasst. Von da an trägt jede Lektion ihren Countdown, auf Home, in der Lektionsliste und im Tab Prüfung: „noch 12 Tage“ liest man, bevor man etwas öffnet.",
        "articles.exam.date2": "Eine Prüfung kann mehrere Lektionen umfassen, und eine Lektion kann in mehreren Prüfungen sein. Angezeigt wird immer **die nächste**: sie ist die erste Einschränkung. Nach dem Tag wandert die Prüfung zu den vergangenen, nichts muss abgeschaltet werden.",
        "articles.exam.mockTitle": "Die Probeprüfung: wie die echte",
        "articles.exam.mock1": "Du wählst die Dauer, {durations}, und die Lektionen. Mika schreibt eine neue Arbeit, von der einfachsten zur anspruchsvollsten Frage, in den fünf Formen. Die Uhr läuft, die gewählte Antwort wird ohne Urteil markiert, du gehst zurück, du änderst deine Meinung. Bei null gibt sich die Arbeit von selbst ab.",
        "articles.exam.mockFigure": "Die abgegebene Arbeit: die Note in deinem System, **Lektion für Lektion**, und darunter die Lösung jeder Frage.",
        "articles.exam.mock2": "Die Lösung kommt am Ende, Frage für Frage: was du geantwortet hast, die richtige Antwort, und warum. Dort lernt man, nicht während der Prüfung, und darum korrigiert die Prüfung unterwegs nichts.",
        "articles.exam.gradeTitle": "Benotet nach deinem System",
        "articles.exam.grade1": "Eine Note von zwanzig, von zehn, ein Prozentsatz, ein Buchstabe, Stufen: das System folgt deinem Land, im Profil gesetzt. Ein französisches 14/20, ein amerikanisches A und eine deutsche 1,3 sind nicht vergleichbar, und ein universeller Wert würde nirgends etwas bedeuten.",
        "articles.exam.grade2": "Jede Lektion der Arbeit bekommt ihre eigene Note. Sie sagt, wohin zurück: eine Lektion unter dem Bestehen am Vorabend ist eine Lektion zum Wiederöffnen, und ihr Weg wartet.",
        "articles.exam.cardsTitle": "Fehler werden zu Karten",
        "articles.exam.cards1": "Eine in der Probeprüfung verfehlte Frage bleibt nicht auf der Arbeit. Mit einem Tipp kommt sie zu den Karten ihrer Lektion, ab morgen fällig, und kehrt im Rhythmus der Abstände zurück, bis sie sitzt.",
        "articles.exam.cardsNote": "Nichts zwingt dich, sie hinzuzufügen. Aber ein einmal gesehener und nie wiederholter Fehler ist genau der, den man am Tag wiederholt.",
        "articles.exam.limitsTitle": "Was der Prüfungsmodus nicht tut",
        "articles.exam.limits1": "Er schafft keine Zeit. Eine Prüfung für morgen auf eine nie geöffnete Lektion zu setzen ergibt einen ehrlichen Countdown und eine schwere Arbeit, und Micabo zeigt sie so, statt zu beruhigen.",
        "articles.exam.limits2": "Er ersetzt auch nicht [[method]]: Notizen, Quiz und Karten tun die Arbeit, die Probeprüfung misst sie nur. Wenn du von Anki kommst, sagt der [[anki]] genau, was sich ändert.",
        "articles.exam.methodLink": "die Methode",
        "articles.exam.ankiLink": "Vergleich",
        "articles.exam.duration": "{minutes} Min für {count} Fragen",
        "articles.exam.durationJoin": ", ",
        "articles.anki.metaTitle": "Micabo oder Anki: was sich wirklich ändert",
        "articles.anki.metaDescription": "Anki ist offen, bewährt und hervorragend. Micabo schreibt die Lektion aus deiner Quelle, ihre Notizen, Quiz und Karten, und benotet dich in einer Probeprüfung. Ein ehrlicher Vergleich, auch da, wo Anki gewinnt.",
        "articles.anki.eyebrow": "Vergleich",
        "articles.anki.h1": "Micabo oder Anki: was sich wirklich ändert",
        "articles.anki.lead1": "Anki ist eine sehr gute Software. Sie ist offen, hat zwanzig Jahre hinter sich und eine Community, die alles dokumentiert hat. Wenn du sie schon nutzt und zufrieden bist, hast du keinen Grund zu wechseln.",
        "articles.anki.lead2": "Der Unterschied liegt nicht in der Kartenplanung: **es ist dasselbe SM-2**. Er liegt davor, in der Lektion, die man nicht schreiben muss, und danach, in der Probeprüfung und ihrem Datum.",
        "articles.anki.tableTitle": "Zeile für Zeile",
        "articles.anki.tableLead": "Drei Zeilen gehen an Anki, und sie stehen so da.",
        "articles.anki.tableCaption": "Vergleich von Micabo und Anki, Kriterium für Kriterium.",
        "articles.anki.colCriterion": "Kriterium",
        "articles.anki.rowAlgo": "Der Algorithmus",
        "articles.anki.rowAlgoMicabo": "SM-2 mit Ankis Standardeinstellungen, drei Knöpfe.",
        "articles.anki.rowAlgoAnki": "Historisch SM-2, heute FSRS, beide einstellbar.",
        "articles.anki.rowWrite": "Karten schreiben",
        "articles.anki.rowWriteMicabo": "Mika schreibt sie mit der Lektion, Thema für Thema. Du liest, antwortest, sie kommen zurück.",
        "articles.anki.rowWriteAnki": "Deine Sache. Dort geht die meiste Zeit hin.",
        "articles.anki.rowLesson": "Verstehen vor dem Wiederholen",
        "articles.anki.rowLessonMicabo": "Notizen pro Thema, ein Quiz, ein Weg aus Schritten: die Lektion vor den Karten.",
        "articles.anki.rowLessonAnki": "Nichts: Anki nimmt an, dass du schon verstanden hast.",
        "articles.anki.rowDate": "Ein Prüfungsdatum",
        "articles.anki.rowDateMicabo": "Ein Countdown auf jeder Lektion und Probeprüfungen in deinem System benotet.",
        "articles.anki.rowDateAnki": "Kein Datum. Man schiebt das Deck von Hand vor.",
        "articles.anki.rowQuestions": "Arten der Befragung",
        "articles.anki.rowQuestionsMicabo": "Multiple Choice, Wahr oder Falsch, Lücke, Reihenfolge, Zuordnung, Karten, Probeprüfung.",
        "articles.anki.rowQuestionsAnki": "Vorder- und Rückseite und selbstgebaute Kartentypen.",
        "articles.anki.rowPlatforms": "Plattformen",
        "articles.anki.rowPlatformsMicabo": "iPhone und Browser, dasselbe Konto auf beiden.",
        "articles.anki.rowPlatformsAnki": "Desktop, Android, iPhone, Browser.",
        "articles.anki.rowDecks": "Fertige Decks",
        "articles.anki.rowDecksMicabo": "Kein Katalog. Deine Lektionen und eine Demo-Lektion zum Anfangen.",
        "articles.anki.rowDecksAnki": "Tausende öffentliche Decks, von ungleicher Qualität.",
        "articles.anki.rowStart": "Der Einstieg",
        "articles.anki.rowStartMicabo": "Ein getipptes Thema, ein Weg, eine Lektion am selben Abend fertig.",
        "articles.anki.rowStartAnki": "Einstellungen verstehen vor der ersten Karte.",
        "articles.anki.costTitle": "Was Anki wirklich kostet: Zeit",
        "articles.anki.cost1": "Ein nützliches Anki-Deck für einen Uni-Kurs sind zwei bis vier Stunden Tippen pro Kapitel: zerlegen, eine Frage pro Idee formulieren, nicht fünf Dinge auf eine Karte stapeln. Diese Arbeit ist lehrreich, das zu leugnen wäre unehrlich. Aber sie ist der Grund, warum man Anki im September öffnet und im November nicht mehr.",
        "articles.anki.costFigure": "Ein getipptes Thema, ein PDF, ein Foto, eine Aufnahme, ein Video, eingefügter Text: **alles kommt so hinein**. Das Tippen verschwindet, Lesen und Fragen bleiben.",
        "articles.anki.cost2": "Micabo übernimmt diesen Schritt. Die Quelle wird zur Lektion: Notizen pro Thema, ein Quiz, Karten. Du liest, antwortest, korrigierst, was nicht stimmt. Es bleibt deine Arbeit, aber sie beginnt beim Lesen statt beim leeren Blatt.",
        "articles.anki.costNote": "Die Kehrseite ist real: eine erzeugte Notiz kann schlecht formuliert oder aus einem schlecht gelesenen Scan sein. Darum kommen die Notizen vor den Karten, und darum schreibt Mika keinen Punkt, den die Quelle nicht nennt. Eine falsche Notiz sieht nicht wie ein Fehler aus.",
        "articles.anki.dateTitle": "Was Anki nicht tut: die Prüfung",
        "articles.anki.date1": "Das ist der echte mechanische Unterschied. Anki bringt Karten zurück, endlos, ohne zu wissen, dass am 14. eine Klausur ist oder wie eine Arbeit auf Zeit aussieht.",
        "articles.anki.date2": "In Micabo setzt du das Datum, jede Lektion trägt ihren Countdown, und du schreibst Probeprüfungen mit Zeit, in deinem System benotet, deren Fehler als Karten zurückkommen. [[exam]] erklärt, wie.",
        "articles.anki.examLink": "Der Prüfungsmodus",
        "articles.anki.pickTitle": "Welches nehmen",
        "articles.anki.pickAnki": "**Bleib bei Anki**, wenn du deinen Planer gern einstellst, FSRS willst, auf Android bist oder ein offenes Werkzeug schätzt, dessen Dateien dir gehören.",
        "articles.anki.pickMicabo": "**Probiere Micabo**, wenn dich nicht das Wiederholen bremst, sondern alles davor, verstehen und Fragen bauen, oder wenn dein Lernen um Prüfungen statt um einen laufenden Strom organisiert ist.",
        "articles.anki.pickBoth": "Und wenn du zögerst: [[method]] ist in beiden dieselbe. Sie tut die Arbeit, nicht die Software, die sie trägt.",
        "articles.anki.methodLink": "die Methode",
    ]

