        "landing.siteTitle": "Micabo - Aprende más rápido con IA",
        "landing.metaDescription": "Escribe un tema o deja un PDF, una foto, una grabación, un vídeo. Mika escribe las notas, los quiz y las tarjetas, y tú sigues el camino hasta el quiz final. Luego un simulacro, calificado como el real.",
