        "landing.questionsMore": "Micabo o Anki: la comparación",
        "landing.faq1q": "¿Mis lecciones son privadas?",
        "landing.faq1a": "Sí. Tus lecciones no están en ningún catálogo: solo tú las ves. La separación está en la base de datos, cada petición se evalúa con tu identidad, así que no existe petición que pueda leer las lecciones de otra persona.",
        "landing.faq2q": "¿Mika se inventa cosas?",
        "landing.faq2a": "Es el riesgo que más en serio nos tomamos, porque una nota falsa no parece un error. Desde un material, Mika escribe solo lo que dice el material, y cuando el texto no zanja un punto, el punto dudoso no aparece. Desde un tema escrito, las notas son las de un curso de referencia, y el quiz te las hace comprobar.",
        "landing.faq3q": "¿Funciona en otros idiomas? ¿Otros sistemas escolares?",
        "landing.faq3a": "Sí. Tu país decide la escala de notas y el idioma de las lecciones. El sitio está disponible en 26 idiomas: cambias el idioma arriba de la página, en el recorrido o en tu perfil.",
        "landing.faq4q": "¿Cuánto dura una lección?",
        "landing.faq4a": "La intro lo dice: a menudo diez a veinticinco minutos hasta el quiz final, más en un capítulo grande. Puedes parar en cualquier paso, el camino te espera ahí.",
        "landing.faq5q": "¿Y si ya uso Anki?",
        "landing.faq5a": "Las tarjetas de Micabo vuelven con la regla de Anki: tres botones, los mismos intervalos. Lo que Micabo añade, Anki no lo hace: escribir la lección, sus notas y sus quiz desde tu material, y calificarte en un simulacro.",
