        "copy.audience": "{views, plural, one {# vista} other {# vistas}} · {adopts, plural, one {# añadido} other {# añadidos}}",
        "copy.practiceReview": "Repasar sin contar",
        "copy.practiceReviewHint": "Repasar sin contar · tus fechas no se mueven",
        "copy.heldBackNew": "{count, plural, one {# tarjeta nueva para más tarde — ya has alcanzado tu ritmo de hoy.} other {# tarjetas nuevas para más tarde — ya has alcanzado tu ritmo de hoy.}}",
        "copy.alreadySubscribed": "Ya estás suscrito.",
        "legal.eyebrow": "Micabo · iPhone, Android y sitio",
        "legal.updated": "Última actualización: {date}.",
        "legal.updatedDate": "23 de octubre de 2026",
        "legal.privacy.metaTitle": "Privacidad",
        "legal.privacy.metaDescription": "Lo que Micabo retiene de usted, en el iPhone, en Android y en el sitio, y lo que puede hacer con ello.",
        "legal.privacy.heading": "Política de privacidad",
        "legal.privacy.linkLabel": "política de privacidad",
        "legal.privacy.intro1": "Esta política describe los datos que Micabo trata cuando utiliza el sitio [[site]], la aplicación iPhone (identificador {bundle}, distribuida en el App Store) o la aplicación Android (paquete {package}, distribuida en Google Play). Los tres clientes comparten la misma cuenta y la misma base. También se aplica si aún no tiene cuenta y solo consulta el sitio.",
        "legal.privacy.intro2": "El responsable del tratamiento es {editor}. Para cualquier pregunta, corrección o supresión: [[contact]].",
        "legal.privacy.whatTitle": "Qué es Micabo",
        "legal.privacy.whatBody": "Micabo transforma un curso (PDF, foto, documento, vídeo) en una ficha y en flashcards, y las hace volver antes de que las olvide. Un modo examen aprieta las revisiones al acercarse una fecha. Puede compartir un curso con amigos o guardarlo para usted.",
        "legal.privacy.dataTitle": "Qué datos tratamos",
        "legal.privacy.dataAccount": "**La cuenta.** Dirección de correo, identificadores que proporcionan Apple o Google si elige esas conexiones, y un nombre de usuario. No almacenamos su contraseña: la conexión por correo se hace con un enlace, no con un secreto que guardaríamos.",
        "legal.privacy.dataSchool": "**El recorrido escolar.** País de estudios, nivel, asignaturas, centro si lo indica. Sirve para escribir la ficha en el idioma y el sistema adecuados, y para mostrarle compañeros del mismo centro si un curso está compartido.",
        "legal.privacy.dataCourses": "**Sus cursos.** Los archivos o enlaces que deposita, el texto extraído, las fichas y las tarjetas generadas, las imágenes de esquemas, los exámenes (nombre, fecha, nota objetivo) y el historial de revisión (cuándo vuelve una tarjeta, cómo la ha valorado).",
        "legal.privacy.dataFriends": "**Los amigos.** Las solicitudes de amistad, su lista de amigos y la visibilidad que pone en cada curso al importarlo: solo usted, sus amigos o los compañeros de su centro. No existe un catálogo público en el que un desconocido tropiece con sus fichas.",
        "legal.privacy.dataSubscription": "**La suscripción.** El estado de su acceso Pro (activo, prueba, cancelado), no el número de su tarjeta. El pago lo cobra Apple en el iPhone (App Store), Google en Android (Google Play) y Stripe en el sitio. RevenueCat sostiene el derecho, para que el iPhone, Android y el navegador coincidan.",
        "legal.privacy.dataWaitlist": "**La lista de espera.** Si deja su dirección antes de tener cuenta, la guardamos para avisarle de la apertura, con la página de la que viene. No está ligada a una cuenta y no es visible desde la aplicación.",
        "legal.privacy.dataFeedback": "**Los comentarios.** Si envía un error o una idea desde la app, guardamos el mensaje, el tipo (error o idea) y el vínculo con su cuenta, para responder. Permanecen 24 meses y luego se borran. No sirven para perfilarle.",
        "legal.privacy.dataUsage": "**El uso de las generaciones.** Un contador por día y por función (ficha, tarjetas, explicación), sin el contenido del curso. Sirve para limitar abusos, no para perfilarle.",
        "legal.privacy.dataDirectory": "**El directorio.** Su nombre de usuario y, si lo ha indicado, su centro. Eso es lo que ve un amigo o un compañero, no su correo ni sus preferencias.",
        "legal.privacy.dataDevice": "**Lo que queda en el aparato.** En el iPhone y en Android, algunas piezas (imágenes de oclusión, audio de una tarjeta) pueden no salir nunca del teléfono. Las respuestas del recorrido de bienvenida quedan primero en el aparato y se escriben en la base una vez abierta la cuenta.",
        "legal.privacy.dataNoSell": "No vendemos sus datos. No mostramos publicidad. No entrenamos un modelo de lenguaje con sus cursos, salvo que un ajuste explícito lo proponga un día — y ese ajuste no existe hoy.",
        "legal.privacy.whyTitle": "Por qué los tratamos",
        "legal.privacy.whyLead": "Las bases jurídicas, en el sentido del RGPD:",
        "legal.privacy.whyContract": "**La ejecución del contrato** — crear la cuenta, importar un curso, escribir la ficha y las tarjetas, revisarlas, sincronizar las apps iPhone y Android y el sitio, gestionar la suscripción.",
        "legal.privacy.whyLegitimate": "**El interés legítimo** — asegurar el servicio, impedir abusos, diagnosticar una avería, medir la audiencia del sitio de forma agregada y leer los comentarios que nos envía. Ese interés no pasa por delante del suyo: el aislamiento está en la base, no solo en la aplicación.",
        "legal.privacy.whyLegal": "**La obligación legal** — conservar lo que la facturación o la contabilidad exigen, el tiempo prescrito.",
        "legal.privacy.whyConsent": "**El consentimiento** — cuando elige compartir un curso, abrir la cámara o conectarse con Apple o Google.",
        "legal.privacy.accessTitle": "Quién tiene acceso",
        "legal.privacy.accessBody": "Sus cursos solo los puede leer usted, salvo que los haya compartido. Cada consulta a la base se evalúa con su identidad: no existe una consulta que pueda pedir los cursos de otra persona. Los comentarios que envía los lee el equipo, en [[contact]]. Nadie más tiene acceso desde la aplicación.",
        "legal.privacy.accessLead": "Algunos prestadores ven una parte de los datos, solo para prestar el servicio:",
        "legal.privacy.accessSupabase": "**Supabase** (Unión Europea, región Estocolmo) — cuenta, base, archivos.",
        "legal.privacy.accessVercel": "**Vercel** — alojamiento del sitio, registros técnicos (dirección IP, URL) y medición de audiencia: el número de páginas vistas, la página de la que viene, el país y el tipo de aparato, sin cookie y sin identificador que le siga. El tratamiento puede tener lugar fuera de la Unión Europea, bajo las cláusulas contractuales tipo del prestador.",
        "legal.privacy.accessApple": "**Apple y Google** — si se conecta con ellos o si paga en el App Store (Apple) o en Google Play (Google).",
        "legal.privacy.accessStripe": "**Stripe** — pago en el sitio.",
        "legal.privacy.accessRevenuecat": "**RevenueCat** — estado de la suscripción, compartido entre el iPhone, Android y el sitio.",
        "legal.privacy.accessFal": "**fal.ai y los modelos que llama** (hoy, modelos de lenguaje, sobre todo de Google) — el texto o la imagen de su curso, el tiempo de escribir la ficha o las tarjetas. No tienen derecho a usarlos para otra cosa que esa generación.",
        "legal.privacy.accessYoutube": "**YouTube / Google** — si importa un vídeo, leemos sus metadatos y subtítulos.",
        "legal.privacy.accessTransfer": "Algunos de estos prestadores están establecidos fuera de la Unión Europea. La transferencia solo tiene entonces lugar para prestar el servicio, y se apoya en las garantías previstas por el RGPD (decisión de adecuación o cláusulas contractuales tipo del prestador).",
        "legal.privacy.cookiesTitle": "Cookies y rastreadores",
        "legal.privacy.cookiesWeb": "El sitio coloca las cookies necesarias para la sesión (reconocerle de una página a otra una vez conectado) y una cookie de preferencia de idioma de interfaz (`micabo.ui_locale`), guardada un año, que retiene el idioma que eligió para la interfaz. Una vez conectado, una cookie `micabo.learner`, guardada un año, retiene en este navegador su nivel exacto y las notas dadas en el recorrido de bienvenida: solo sirve para escribir sus lecciones al nivel adecuado. No colocamos cookie de medición de audiencia, ni de publicidad, ni de rastreo entre sitios. El sitio sí cuenta sus visitas, pero sin escribir nada en su aparato: la medición retiene una página vista, su procedencia, un país, un tipo de aparato, y nada que permita reconocerle de una visita a otra ni en otro sitio. Por eso no hay banner de consentimiento: no hay nada que rechazar de ese lado.",
        "legal.privacy.cookiesIos": "Las apps iPhone y Android no usan cookies. Guardan un token de sesión en el almacenamiento protegido del aparato: el llavero en el iPhone, el almacenamiento privado de la app en Android.",
        "legal.privacy.retentionTitle": "Cuánto tiempo los guardamos",
        "legal.privacy.retentionWhile": "Mientras exista la cuenta. Los comentarios se van a más tardar a los 24 meses. Si la elimina, desde Ajustes en el sitio o en las apps iPhone y Android, o escribiéndonos, borramos el perfil, los cursos (incluido el texto extraído), las fichas, las tarjetas, el historial, los exámenes, las amistades, los contadores de uso, los comentarios y la dirección que haya dejado en la lista de espera.",
        "legal.privacy.retentionShared": "Un curso que ha compartido desaparece para sus amigos cuando lo elimina. Un amigo que ya ha revisado sus tarjetas conserva su propio historial, no su documento.",
        "legal.privacy.retentionAfter": "Tras la eliminación, queda en los prestadores lo que la ley o su contrato impone: facturas de Stripe, Apple o Google, identificador de suscripción de RevenueCat, registros técnicos (Vercel, Supabase) unas semanas. fal.ai recibe el texto el tiempo de escribir la ficha; no le pedimos que lo conserve.",
        "legal.privacy.rightsTitle": "Sus derechos",
        "legal.privacy.rightsBody": "Puede acceder a sus datos, corregirlos, exportarlos, oponerse a un tratamiento o pedir la supresión. Para descargar una copia: Ajustes → «Descargar mis datos». Para borrar la cuenta: Ajustes → «Eliminar la cuenta», en el sitio o en las apps iPhone y Android. También puede escribir a [[contact]]. Respondemos en el plazo de un mes.",
        "legal.privacy.rightsCnil": "También puede presentar una reclamación ante la CNIL (cnil.fr).",
        "legal.privacy.minorsTitle": "Menores",
        "legal.privacy.minorsBody": "Micabo se dirige a estudiantes, también de bachillerato. No pedimos la fecha de nacimiento. Si tiene menos de quince años, el uso del servicio debe hacerse con el acuerdo de un titular de la patria potestad. No usamos los datos de un menor para publicidad ni para un perfilado comercial.",
        "legal.privacy.iosTitle": "Las apps iPhone y Android, además del sitio",
        "legal.privacy.iosBody": "Las apps pueden pedir acceso a sus fotos, a sus archivos o a la cámara para importar un curso. No es obligatorio: el sitio acepta un archivo depositado. Las notificaciones, si las autoriza, solo sirven para recordarle una revisión. La misma cuenta abre la app iPhone, la app Android y el sitio.",
        "legal.privacy.changesTitle": "Modificaciones",
        "legal.privacy.changesBody": "Si esta política cambia de forma sustancial, actualizamos la fecha al inicio de la página. El uso continuado después de esa fecha vale para la nueva versión, salvo que la ley exija un acuerdo distinto.",
        "legal.privacy.changesAlso": "Las [[terms]] completan este texto.",
        "legal.terms.metaTitle": "Condiciones de uso",
        "legal.terms.metaDescription": "Las reglas del servicio Micabo, para el iPhone, Android y el sitio: cuenta, cursos, suscripción, responsabilidades.",
        "legal.terms.heading": "Condiciones de uso",
        "legal.terms.linkLabel": "condiciones de uso",
        "legal.terms.intro1": "Estas condiciones rigen el uso de Micabo — el sitio [[site]], la aplicación iPhone ({bundle}, en el App Store) y la aplicación Android ({package}, en Google Play). Al crear una cuenta o al usar el servicio, las acepta. Si no está de acuerdo, no abra una cuenta.",
        "legal.terms.intro2": "El editor es {editor}. Contacto: [[contact]].",
        "legal.terms.serviceTitle": "El servicio",
        "legal.terms.serviceBody": "Micabo lee un documento de curso que usted deposita y escribe una ficha y flashcards. Las hace volver según una repetición espaciada (la misma regla SM-2 en el iPhone, en Android y en el sitio). Puede fijar la fecha de un examen: el plan de revisión se aprieta entonces hacia ese día. Una misma cuenta abre los tres clientes.",
        "legal.terms.servicePro": "Una parte del servicio es accesible sin suscripción. El acceso Pro (cursos y tarjetas más allá del techo gratuito, según la oferta mostrada en el momento de la compra) es de pago.",
        "legal.terms.accountTitle": "La cuenta",
        "legal.terms.accountBody": "Puede conectarse con Apple, Google o un enlace enviado por correo. Es responsable del acceso a su buzón y a esas cuentas de terceros. Una sola cuenta por persona.",
        "legal.terms.accountDelete": "Puede eliminar la cuenta desde Ajustes, en el sitio o en las apps iPhone y Android. Eso borra sus cursos, sus tarjetas y su historial. Eliminar la cuenta no cancela una suscripción contratada en el App Store o en Google Play: cancélela en la tienda. Las compras ya cobradas por Apple, Google o Stripe siguen sujetas a sus reglas de reembolso.",
        "legal.terms.coursesTitle": "Sus cursos",
        "legal.terms.coursesOwn": "Usted conserva la propiedad de lo que deposita. Solo nos da el derecho, limitado y revocable, de leerlo, almacenarlo y transformarlo en ficha y en tarjetas, para prestarle el servicio — incluido enviarlo a un modelo de lenguaje el tiempo de la generación.",
        "legal.terms.coursesRights": "Solo deposita documentos que tiene derecho a usar. Un temario de su profesor, sus apuntes, un vídeo cuya importación está autorizada: sí. Una obra entera copiada, el trabajo de otro, un contenido ilegal: no. Podemos retirar un curso o cerrar una cuenta que rompa esta regla.",
        "legal.terms.coursesShare": "La visibilidad se decide al importar. Un curso privado se queda con usted. Un curso compartido solo lo ven las personas que ha elegido (amigos o compañeros del centro). No es una biblioteca abierta a todos.",
        "legal.terms.notTitle": "Lo que Micabo no es",
        "legal.terms.notBody": "La ficha y las tarjetas se generan automáticamente. Pueden equivocarse, omitir un pasaje o leer mal un escaneo. Micabo no es un profesor ni una garantía de nota. Usted sigue siendo responsable de lo que aprende y de lo que entrega el día del examen.",
        "legal.terms.notInvent": "Nos esforzamos en no inventar una definición cuando el documento no la lleva. Eso no hace el resultado infalible.",
        "legal.terms.subTitle": "La suscripción",
        "legal.terms.subPrices": "Los precios, la duración y la prueba eventual son los mostrados antes del pago. Pueden cambiar para las compras nuevas; una suscripción ya en curso conserva sus condiciones hasta su renovación.",
        "legal.terms.subIos": "**En el iPhone**, el pago pasa por el App Store: la cancelación, la renovación y los reembolsos siguen las reglas de Apple, y la suscripción se gestiona o se cancela en los ajustes de su cuenta Apple (Ajustes → su nombre → Suscripciones). **En Android**, el pago pasa por Google Play: la cancelación, la renovación y los reembolsos siguen las reglas de Google Play, y la suscripción se gestiona o se cancela en la app Google Play (Pagos y suscripciones → Suscripciones).",
        "legal.terms.subWeb": "**En el sitio**, el pago pasa por Stripe. La cancelación se hace desde el espacio de facturación indicado en el perfil, o escribiéndonos. Una prueba, si se ofrece, solo se convierte en pago si la deja llegar a su término.",
        "legal.terms.subBoth": "El acceso Pro comprado de un lado vale de los otros: la misma cuenta es Pro en el iPhone, en Android y en el sitio. Un incidente de pago puede abrir un periodo de gracia; no cerramos el acceso a la primera hora.",
        "legal.terms.forbidTitle": "Lo que no hace",
        "legal.terms.forbidHarm": "Usar el servicio para perjudicar a alguien, acosar o hacer trampas de un modo que viole el reglamento de su centro.",
        "legal.terms.forbidAccess": "Intentar acceder a los cursos de otra cuenta, eludir el aislamiento o saturar el servicio a propósito.",
        "legal.terms.forbidResell": "Revender el acceso, extraer el servicio con un robot más allá de un uso humano normal, o copiar Micabo para hacer un producto competidor a partir de nuestras generaciones.",
        "legal.terms.forbidIllegal": "Depositar contenidos ilegales, de odio o que atenten contra la vida privada de terceros.",
        "legal.terms.availTitle": "Disponibilidad",
        "legal.terms.availBody": "Hacemos lo posible para que las apps y el sitio sigan accesibles. Un mantenimiento, una avería de un prestador (alojamiento, modelo, tienda) o un error de generación puede interrumpir el servicio. No ofrecemos garantía de resultado escolar ni de disponibilidad ininterrumpida.",
        "legal.terms.liabilityTitle": "Responsabilidad",
        "legal.terms.liabilityConsumer": "Si es consumidor, sus derechos legales (garantía, mediación, cláusulas abusivas) se aplican y estas condiciones no los apartan.",
        "legal.terms.liabilityLimit": "Más allá, Micabo no es responsable de las notas obtenidas, de una ficha incompleta, de un olvido el día D o de un daño indirecto (tiempo perdido, examen fallido). Nuestra responsabilidad, si se retuviera por un incumplimiento que nos sea imputable, se limita al importe que nos ha abonado en los últimos doce meses — salvo falta grave, dolo o lesión a la integridad de la persona.",
        "legal.terms.minorsTitle": "Menores",
        "legal.terms.minorsBody": "Si tiene menos de quince años, un titular de la patria potestad debe aceptar estas condiciones y vigilar el uso. Compartir un curso con amigos sigue bajo su responsabilidad y bajo la de ellos.",
        "legal.terms.lawTitle": "Derecho aplicable",
        "legal.terms.lawBody": "Estas condiciones se rigen por el derecho francés. En caso de litigio, y tras un intento de resolución por escrito a [[contact]], son competentes los tribunales franceses — sin perjuicio de las normas de protección del consumidor que le fueran más favorables.",
        "legal.terms.changesTitle": "Modificaciones",
        "legal.terms.changesBody": "Podemos actualizar estas condiciones. La fecha al inicio de la página es la que cuenta. Un cambio que afecte al precio de una suscripción en curso se le anuncia antes de la renovación.",
        "legal.terms.changesAlso": "La [[privacy]] describe el tratamiento de sus datos.",
        "articles.shared.navAria": "Páginas",
        "articles.shared.nextTitle": "Leer después",
        "articles.shared.ctaTitle": "Escribe un tema, mira en qué se convierte.",
        "articles.shared.ctaBody": "En el sitio como en iPhone, con la misma cuenta y las mismas lecciones.",
        "articles.method.metaTitle": "El método: repetición espaciada y recuerdo activo, dentro de una lección",
        "articles.method.metaDescription": "Releer un curso no hace que se retenga. Lo que se recupera de memoria se queda, sobre todo si la pregunta vuelve justo antes del olvido. Cómo una lección de Micabo aplica el recuerdo activo y el espaciado, con los intervalos reales.",
        "articles.method.h1": "Releer no basta. Recordar, sí.",
        "articles.method.lead1": "Una página releída cuatro veces da una sensación de dominio que no sobrevive al examen. Lo que mejora es el reconocimiento: «sí, esto ya lo vi». Y el reconocimiento no es lo que pide un examen.",
        "articles.method.lead2": "Lo que se queda es lo que tuviste que **recuperar de memoria**, y lo que vuelve **justo antes de olvidarlo**. Dos ideas antiguas, medidas desde hace más de un siglo, y dos ideas penosas de aplicar a mano. Eso es lo que una lección de Micabo hace por ti.",
        "articles.method.activeTitle": "El recuerdo activo: la pregunta antes que la respuesta",
        "articles.method.active1": "Ponerse a prueba funciona mejor que releer, incluso cuando uno se equivoca. El esfuerzo de recuperación es lo que refuerza la huella: una respuesta que buscas tres segundos vale más que una que lees en uno.",
        "articles.method.active2": "Por eso cada tema de una lección termina con **una pregunta**, y cada tramo con un checkpoint: no pasas a lo siguiente sin recuperar lo que acabas de leer. Y una pregunta fallada no desaparece, se vuelve una tarjeta.",
        "articles.method.spacingTitle": "El espaciado: volver en el último momento útil",
        "articles.method.spacing1": "Sin repaso, lo que se retiene de un curso cae a casi nada en un mes. Cada recuerdo pone el contador a cien, y la bajada siguiente es **más lenta que la anterior**. Repasar en el momento justo no pide más tiempo: pide menos, a medida que la memoria se estabiliza.",
        "articles.method.spacing2": "Lo interesante no es la forma de cada curva, es **dónde se separan**: el primer repaso. Lo que automatizan las tarjetas de una lección es la elección de ese instante, tarjeta por tarjeta.",
        "articles.method.lessonTitle": "Primero la lección, luego las tarjetas",
        "articles.method.lesson1": "Una tarjeta supone que ya has entendido. Ponerse a prueba sobre una noción que no has leído es aprender una respuesta de memoria sin saber de qué habla. Por eso Mika escribe primero **las notas** de cada tema: cortas, con las palabras clave a la vista, y un recuadro para lo que hay que recordar.",
        "articles.method.lessonFigure": "Las notas de un tema, tal como Mika las escribe: la palabra clave en color, la definición, **lo que hay que recordar** en un recuadro. Los mismos bloques que en la app.",
        "articles.method.lesson2": "Luego vienen el quiz y las tarjetas, sacados de esas notas y no del documento en bruto. Lees, respondes, y solo entonces las tarjetas vuelven, al ritmo del espaciado.",
        "articles.method.plannerTitle": "Lo que Micabo calcula con cada nota",
        "articles.method.planner1": "Las tarjetas se planifican con **SM-2**, la regla de Anki con sus ajustes por defecto. Una tarjeta nueva pasa por tramos cortos, {steps}, antes de salir en días. Luego, cada nota multiplica el intervalo por una facilidad propia de la tarjeta, que parte de {ease} y se mueve con tus respuestas.",
        "articles.method.planner2": "Tres botones: Otra vez, Bien, Fácil. «Lo sé / no lo sé» no distingue la tarjeta recuperada con esfuerzo de la que vino sola, y es ese margen el que decide la fecha siguiente. Esto es lo que anuncian los tres botones sobre una tarjeta nueva:",
        "articles.method.buttonsCaption": "Los intervalos los calcula el planificador de la app, no están escritos a mano.",
        "articles.method.planner3": "El intervalo está escrito en el botón **antes** de pulsar. A un planificador que decide por su cuenta se le desobedece pronto: marcas «fácil» para ir más rápido, la tarjeta se va a tres semanas, y la redescubres el día del examen.",
        "articles.method.stepMinutes": "{n} min",
        "articles.method.stepJoin": ", luego ",
        "articles.method.formatsTitle": "Cinco formas de ser preguntado sobre las mismas notas",
        "articles.method.formats1": "El recuerdo activo no se limita al anverso y reverso. Sobre un mismo tema, el quiz plantea opción múltiple, verdadero o falso, huecos, ordenar, asociar. Las preguntas vienen de tus notas, y cada respuesta dice al instante si es correcta, y por qué.",
        "articles.method.formatsFigure": "Una pregunta del quiz, la de verdad: responde, te corrige. **Las cinco formas salen de las mismas notas**, de la más simple a la más exigente.",
        "articles.method.limitsTitle": "Lo que el método no hace",
        "articles.method.limits1": "La repetición espaciada coloca los repasos. No entiende por ti, no redacta un ensayo, y no recupera un capítulo empezado la víspera: no hay espaciado posible en una noche.",
        "articles.method.limits2": "También ignora las fechas, por construcción: SM-2 no sabe que hay un examen dentro de tres semanas. Eso es exactamente lo que el [[exam]] completa.",
        "articles.method.examLink": "modo examen",
        "articles.method.note": "Una lección se abre libremente en cualquier paso: nada obliga a terminar el camino de una vez. Lo que el espaciado pide es solo volver cuando las tarjetas lo digan.",
        "articles.exam.metaTitle": "El modo examen: una fecha, días que quedan, un simulacro",
        "articles.exam.metaDescription": "Das la fecha de tu examen, Micabo cuenta los días en cada lección del temario. El simulacro es cronometrado, sin corrección durante la prueba, calificado con la escala de tu país, y tus errores se vuelven tarjetas.",
        "articles.exam.h1": "Das la fecha. Micabo cuenta los días, y te entrena.",
        "articles.exam.lead1": "Aprender una lección y aprobar una prueba no son lo mismo. El día D se escribe contra reloj, sin ver si se acierta, y se califica con una escala. Nada de eso ocurre en un repaso ordinario.",
        "articles.exam.lead2": "El modo examen da a tus lecciones lo que les falta: **una fecha**, y una prueba que se parece a la real. Pones el día, eliges las lecciones del temario, y te entrenas con simulacros.",
        "articles.exam.dateTitle": "Una fecha, y los días que quedan",
        "articles.exam.date1": "Un examen es un nombre, un día y las lecciones que cubre. Desde ahí, cada lección del temario lleva su cuenta atrás, en Home, en la lista de lecciones y en la pestaña Examen: «quedan 12 días» se lee antes de abrir nada.",
        "articles.exam.date2": "Un examen puede cubrir varias lecciones, y una lección puede estar en varios exámenes. Siempre se muestra **el más cercano**: es la primera restricción. Pasado el día, el examen pasa a los pasados, y no hay nada que desactivar.",
        "articles.exam.mockTitle": "El simulacro: como el real",
        "articles.exam.mock1": "Eliges la duración, {durations}, y las lecciones. Mika escribe un examen nuevo, de lo más simple a lo más exigente, en las cinco formas de pregunta. El cronómetro corre, la respuesta elegida se resalta sin veredicto, vuelves atrás, cambias de idea. A cero, el examen se entrega solo.",
        "articles.exam.mockFigure": "El examen entregado: la nota en tu escala, **lección por lección**, y la corrección de cada pregunta debajo.",
        "articles.exam.mock2": "La corrección llega al final, pregunta por pregunta: lo que respondiste, la respuesta correcta, y por qué. Ahí se aprende, no durante la prueba, y por eso la prueba no corrige nada por el camino.",
        "articles.exam.gradeTitle": "Calificado con tu escala",
        "articles.exam.grade1": "Una nota sobre veinte, sobre diez, un porcentaje, una letra, tramos: la escala sigue tu país, fijado en tu perfil. Un 14/20 francés, una A americana y un 1,3 alemán no se comparan, y una puntuación universal no significaría nada en ningún sitio.",
        "articles.exam.grade2": "Cada lección del examen recibe su propia nota. Es la que dice adónde volver: una lección por debajo del aprobado la víspera es una lección que reabrir, y su camino espera.",
        "articles.exam.cardsTitle": "Los errores se vuelven tarjetas",
        "articles.exam.cards1": "Una pregunta fallada en el simulacro no se queda en el examen. Con un toque se une a las tarjetas de su lección, para mañana, y vuelve al ritmo del espaciado hasta que se queda.",
        "articles.exam.cardsNote": "Nada te obliga a añadirlas. Pero un error visto una vez y nunca repasado es exactamente el que se repite el día D.",
        "articles.exam.limitsTitle": "Lo que el modo examen no hace",
        "articles.exam.limits1": "No fabrica tiempo. Declarar un examen para mañana sobre una lección que no has abierto da una cuenta atrás honesta y un examen difícil, y Micabo los muestra tal cual en vez de tranquilizar.",
        "articles.exam.limits2": "Tampoco sustituye [[method]]: las notas, los quiz y las tarjetas hacen el trabajo, el simulacro solo lo mide. Si vienes de Anki, la [[anki]] dice exactamente qué cambia.",
        "articles.exam.methodLink": "el método",
        "articles.exam.ankiLink": "comparación",
        "articles.exam.duration": "{minutes} min para {count} preguntas",
        "articles.exam.durationJoin": ", ",
        "articles.anki.metaTitle": "Micabo o Anki: lo que cambia de verdad",
        "articles.anki.metaDescription": "Anki es abierto, probado y excelente. Micabo escribe la lección desde tu material, sus notas, quiz y tarjetas, y te califica en un simulacro. Comparación honesta, incluso donde gana Anki.",
        "articles.anki.eyebrow": "Comparación",
        "articles.anki.h1": "Micabo o Anki: lo que cambia de verdad",
        "articles.anki.lead1": "Anki es un programa muy bueno. Es abierto, tiene veinte años de recorrido y una comunidad que lo ha documentado todo. Si ya lo usas y te va bien, no tienes ninguna razón para cambiar.",
        "articles.anki.lead2": "La diferencia no está en la planificación de las tarjetas: **es el mismo SM-2**. Está antes, en la lección que no hay que escribir, y después, en el simulacro y su fecha.",
        "articles.anki.tableTitle": "Línea por línea",
        "articles.anki.tableLead": "Tres líneas van para Anki, y están escritas tal cual.",
        "articles.anki.tableCaption": "Comparación de Micabo y Anki, criterio por criterio.",
        "articles.anki.colCriterion": "Criterio",
        "articles.anki.rowAlgo": "El algoritmo",
        "articles.anki.rowAlgoMicabo": "SM-2, con los ajustes por defecto de Anki, tres botones.",
        "articles.anki.rowAlgoAnki": "SM-2 históricamente, FSRS hoy, y ambos se ajustan.",
        "articles.anki.rowWrite": "Escribir las tarjetas",
        "articles.anki.rowWriteMicabo": "Mika las escribe con la lección, tema por tema. Lees, respondes, vuelven.",
        "articles.anki.rowWriteAnki": "Tú. Ahí se va la mayor parte del tiempo.",
        "articles.anki.rowLesson": "Entender antes de repasar",
        "articles.anki.rowLessonMicabo": "Notas por tema, un quiz, un camino de pasos: la lección antes que las tarjetas.",
        "articles.anki.rowLessonAnki": "Nada: Anki supone que ya has entendido.",
        "articles.anki.rowDate": "Una fecha de examen",
        "articles.anki.rowDateMicabo": "Una cuenta atrás en cada lección, y simulacros calificados con tu escala.",
        "articles.anki.rowDateAnki": "Sin noción de fecha. Se adelanta el mazo a mano.",
        "articles.anki.rowQuestions": "Las formas de ser preguntado",
        "articles.anki.rowQuestionsMicabo": "Opción múltiple, verdadero o falso, hueco, ordenar, asociar, tarjetas, simulacro.",
        "articles.anki.rowQuestionsAnki": "Anverso y reverso, y los tipos de tarjeta que uno construye.",
        "articles.anki.rowPlatforms": "Las plataformas",
        "articles.anki.rowPlatformsMicabo": "iPhone y navegador, la misma cuenta en ambos.",
        "articles.anki.rowPlatformsAnki": "Ordenador, Android, iPhone, navegador.",
        "articles.anki.rowDecks": "Los mazos hechos",
        "articles.anki.rowDecksMicabo": "Ningún catálogo. Tus lecciones, y una lección de demostración para empezar.",
        "articles.anki.rowDecksAnki": "Miles de mazos públicos, de calidad desigual.",
        "articles.anki.rowStart": "La puesta en marcha",
        "articles.anki.rowStartMicabo": "Un tema escrito, un camino que seguir, una lección terminada esa misma tarde.",
        "articles.anki.rowStartAnki": "Ajustes que entender antes de la primera tarjeta.",
        "articles.anki.costTitle": "Lo que Anki cuesta de verdad: tiempo",
        "articles.anki.cost1": "Un mazo de Anki útil para un curso universitario son de dos a cuatro horas de escritura por capítulo: trocear, formular una pregunta por idea, no apilar cinco cosas en una tarjeta. Ese trabajo es instructivo, negarlo sería deshonesto. Pero es el trabajo por el que uno abre Anki en septiembre y ya no en noviembre.",
        "articles.anki.costFigure": "Un tema escrito, un PDF, una foto, un audio, un vídeo, un texto pegado: **todo entra tal cual**. La escritura desaparece, la lectura y las preguntas se quedan.",
        "articles.anki.cost2": "Micabo asume ese paso. El material se vuelve una lección: notas por tema, un quiz, tarjetas. Lees, respondes, corriges lo que no va. Sigue siendo tu trabajo, pero empieza en la lectura en vez de en la página en blanco.",
        "articles.anki.costNote": "El reverso es real: una nota generada puede estar mal formulada o salir de un escaneo mal leído. Por eso las notas van antes que las tarjetas, y por eso Mika no escribe un punto del que el material no habla. Una nota equivocada no parece un error.",
        "articles.anki.dateTitle": "Lo que Anki no hace: la prueba",
        "articles.anki.date1": "Es la verdadera diferencia de mecánica. Anki hace volver tarjetas, indefinidamente, sin saber que hay un parcial el 14 ni cómo es un examen contra reloj.",
        "articles.anki.date2": "En Micabo, pones la fecha, cada lección lleva su cuenta atrás, y haces simulacros cronometrados, calificados con tu escala, cuyos errores vuelven como tarjetas. [[exam]] detalla cómo.",
        "articles.anki.examLink": "El modo examen",
        "articles.anki.pickTitle": "Cuál elegir",
        "articles.anki.pickAnki": "**Quédate en Anki** si te gusta ajustar tu planificador, si quieres FSRS, si estás en Android, o si valoras una herramienta abierta cuyos archivos posees.",
        "articles.anki.pickMicabo": "**Prueba Micabo** si lo que te bloquea no es el repaso sino todo lo anterior, entender y fabricar las preguntas, o si tus repasos se organizan alrededor de exámenes más que de un flujo continuo.",
        "articles.anki.pickBoth": "Y si dudas: [[method]] es el mismo en los dos. Es el que hace el trabajo, no el programa que lo lleva.",
        "articles.anki.methodLink": "el método",
    ]

