        "landing.siteTitle": "Micabo - Yapay zekâyla daha hızlı öğren",
        "landing.metaDescription": "Bir konu yaz ya da PDF, fotoğraf, ses kaydı, video bırak. Mika notları, quizleri ve kartları yazar, sen final quize kadar yolu izlersin. Sonra gerçeği gibi notlanan bir deneme sınavı.",
        "landing.ogDescription": "Bir konu ders yoluna dönüşür: notlar, quizler, kartlar, deneme sınavı.",
        "landing.ogDescriptionShort": "Bir konu ders yoluna dönüşür: notlar, quizler, kartlar, deneme sınavı.",
        "landing.schemaDescription": "Micabo bir konuyu ya da belgeyi derse dönüştürür: notlar, quizler ve kartlarla adımlardan oluşan bir yol, sonra ülkenin not sistemine göre notlanan deneme sınavları.",
        "landing.manifestDescription": "Bir konu yaz, bir kaynak bırak. Mika dersi yazar, sen yolu izlersin.",
        "landing.howEyebrow": "Nasıl çalışır",
        "landing.howTitle": "Ders notundan derse, üç adımda.",
        "landing.howNote": "Hazırlanacak bir şey yok, yeniden yazılacak bir şey yok. Elindekini yüklersin, gerisini Mika halleder.",
        "landing.stepEyebrow": "Adım {n}",
        "landing.step1Title": "Ders notunu yüklersin.",
        "landing.step1Body": "Bir PDF, bir Word belgesi, tahtanın fotoğrafı, bir YouTube videosu, bir ses kaydı ya da yazılmış iki kelime: aynı anda en fazla beş materyal.",
        "landing.step2Title": "Mika dersi yazar.",
        "landing.step2Body": "Konulara ayrılmış bir plan, ardından her konu için anahtar kelimeleriyle net notlar, bir quiz ve kartlar. Diğerleri yazılırken ilk konu hazır olur.",
        "landing.step3Title": "Yolu takip edersin.",
        "landing.step3Body": "Adım adım, final quizine kadar. Yanlış cevapladığın bir soru yarın tekrar edeceğin bir karta dönüşür, sonunda da deneme sınavı seni bekler.",
        "landing.methodMore": "Yöntemi ayrıntılı oku",
        "landing.examMore": "Sınav nasıl hazırlanır",
        "landing.questionsEyebrow": "Sorular",
        "landing.questionsTitle": "Bize sorulanlar.",
        "landing.questionsNote": "İlk dersten önce akla gelenler.",
        "landing.questionsMore": "Micabo mu Anki mi: karşılaştırma",
        "landing.faq1q": "Derslerim özel mi?",
        "landing.faq1a": "Evet. Derslerin hiçbir katalogda yok: yalnızca sen görürsün. Ayrım veritabanında; her istek senin kimliğinle değerlendirilir, dolayısıyla başkasının derslerini okuyabilecek bir istek yoktur.",
        "landing.faq2q": "Mika uydurur mu?",
        "landing.faq2a": "En ciddiye aldığımız risk bu, çünkü yanlış bir not hataya benzemez. Bir kaynaktan Mika yalnızca kaynağın söylediğini yazar; metin bir noktayı netleştirmiyorsa o nokta görünmez. Yazılan bir konudan notlar bir referans dersinkidir ve quiz bunları kontrol ettirir.",
        "landing.faq3q": "Başka dillerde çalışır mı? Başka okul sistemlerinde?",
        "landing.faq3a": "Evet. Ülken not sistemini ve derslerin dilini belirler. Sitenin kendisi 26 dilde kullanılabilir: dili sayfanın üstünden, akışta ya da profilinden değiştirirsin.",
        "landing.faq4q": "Bir ders ne kadar sürer?",
        "landing.faq4a": "Giriş söyler: final quize kadar genellikle on ila yirmi beş dakika, büyük bir bölümde daha fazla. Herhangi bir adımda durabilirsin, yol seni orada bekler.",
        "landing.faq5q": "Zaten Anki kullanıyorsam?",
        "landing.faq5a": "Micabo'nun kartları Anki'nin kuralıyla geri gelir: üç düğme, aynı aralıklar. Micabo'nun eklediğini Anki yapmaz: dersi, notlarını ve quizlerini kaynağından yazmak ve seni deneme sınavında notlamak.",
        "landing.closingTitle": "Bir sonraki sınavının tarihi var. İlk dersin şimdi başlıyor.",
