        "copy.heldBackNew": "{count, plural, one {# yeni kart sonraya — bugünkü tempon doldu.} other {# yeni kart sonraya — bugünkü tempon doldu.}}",
        "copy.alreadySubscribed": "Zaten abonesin.",
        "legal.eyebrow": "Micabo · iPhone, Android ve site",
        "legal.updated": "Son güncelleme: {date}.",
        "legal.updatedDate": "23 Ekim 2026",
        "legal.privacy.metaTitle": "Gizlilik",
        "legal.privacy.metaDescription": "Micabo'nun iPhone'da, Android'de ve sitede sizden ne tuttuğu, ve bunlarla ne yapabileceğiniz.",
        "legal.privacy.heading": "Gizlilik politikası",
        "legal.privacy.linkLabel": "gizlilik politikası",
        "legal.privacy.intro1": "Bu politika, [[site]] sitesini, iPhone uygulamasını (tanımlayıcı {bundle}, App Store'da dağıtılır) veya Android uygulamasını (paket {package}, Google Play'de dağıtılır) kullandığınızda Micabo'nun işlediği verileri anlatır. Üç istemci aynı hesabı ve aynı veritabanını paylaşır. Henüz hesabınız yokken siteye bakıyorsanız da geçerlidir.",
        "legal.privacy.intro2": "Veri sorumlusu {editor}'dur. Soru, düzeltme veya silme için: [[contact]].",
        "legal.privacy.whatTitle": "Micabo nedir",
        "legal.privacy.whatBody": "Micabo bir dersi (PDF, fotoğraf, belge, video) özet kâğıdına ve kartlara dönüştürür, sonra unutmadan önce geri getirir. Sınav modu, bir tarihe yaklaşırken tekrarları sıkılaştırır. Bir dersi arkadaşlarınızla paylaşabilir veya kendinize saklayabilirsiniz.",
        "legal.privacy.dataTitle": "Hangi verileri işliyoruz",
        "legal.privacy.dataAccount": "**Hesap.** E-posta adresi, bu giriş yöntemlerini seçerseniz Apple veya Google'ın verdiği tanımlayıcılar ve bir kullanıcı adı. Parolanızı saklamıyoruz: e-posta ile giriş, saklayacağımız bir sırla değil, bir bağlantıyla yapılır.",
        "legal.privacy.dataSchool": "**Öğrenim yolu.** Öğrenim ülkesi, kademe, dersler, verirseniz okul. Özet kâğıdını doğru dilde ve doğru sistemde yazmak ve bir ders paylaşılmışsa aynı okuldaki arkadaşları göstermek için kullanılır.",
        "legal.privacy.dataCourses": "**Dersleriniz.** Yüklediğiniz dosyalar veya bağlantılar, bunlardan çıkarılan metin, üretilen özet kâğıtları ve kartlar, şema görselleri, sınavlar (ad, tarih, hedef not) ve tekrar geçmişi (bir kartın ne zaman döndüğü, nasıl puanladığınız).",
        "legal.privacy.dataFriends": "**Arkadaşlar.** Arkadaşlık istekleri, arkadaş listeniz ve içe aktarırken her derse koyduğunuz görünürlük: yalnızca siz, arkadaşlarınız veya okuldaki arkadaşlarınız. Bir yabancının özet kâğıtlarınıza rastlayacağı genel bir katalog yoktur.",
        "legal.privacy.dataSubscription": "**Abonelik.** Pro erişiminizin durumu (aktif, deneme, iptal), kart numaranız değil. Ödemeyi iPhone'da Apple (App Store), Android'de Google (Google Play), sitede Stripe alır. RevenueCat hakkı tutar, böylece iPhone, Android ve tarayıcı aynı fikirde olur.",
        "legal.privacy.dataWaitlist": "**Bekleme listesi.** Hesabınız olmadan önce adresinizi bırakırsanız, açılışı haber vermek için geldiğiniz sayfayla birlikte saklarız. Bir hesaba bağlı değildir ve uygulamadan görünmez.",
        "legal.privacy.dataFeedback": "**Geri bildirimler.** Uygulamadan bir hata veya fikir gönderirseniz, yanıtlamak için iletiyi, türü (hata veya fikir) ve hesabınızla bağını saklarız. 24 ay kalır, sonra silinir. Sizi profillemek için kullanılmaz.",
        "legal.privacy.dataUsage": "**Üretimlerin kullanımı.** Günlük ve işlev başına bir sayaç (özet, kartlar, açıklama), dersin içeriği olmadan. Kötüye kullanımı sınırlamak içindir, sizi profillemek için değil.",
        "legal.privacy.dataDirectory": "**Rehber.** Kullanıcı adınız ve belirttiyseniz okulunuz. Bir arkadaşın veya okul arkadaşının gördüğü budur; e-postanız veya tercihleriniz değil.",
        "legal.privacy.dataDevice": "**Cihazda kalan.** iPhone'da ve Android'de bazı parçalar (örtme görselleri, bir kartın sesi) telefonu hiç terk etmeyebilir. Karşılama yolunun yanıtları önce cihazda kalır, hesap açılınca veritabanına yazılır.",
        "legal.privacy.dataNoSell": "Verilerinizi satmıyoruz. Reklam göstermiyoruz. Bir gün açık bir ayar bunu önermedikçe — ve bugün böyle bir ayar yoktur — dil modelini derslerinizle eğitmiyoruz.",
        "legal.privacy.whyTitle": "Neden işliyoruz",
        "legal.privacy.whyLead": "KVKK / GDPR anlamında hukuki dayanaklar:",
        "legal.privacy.whyContract": "**Sözleşmenin ifası** — hesabı oluşturmak, bir dersi içe aktarmak, özet kâğıdını ve kartları yazmak, tekrarlamak, iPhone ve Android uygulamalarını siteyle eşitlemek, aboneliği yönetmek.",
        "legal.privacy.whyLegitimate": "**Meşru menfaat** — hizmeti güvenceye almak, kötüye kullanımı engellemek, bir arızayı teşhis etmek, sitenin kitlesini toplu biçimde ölçmek ve gönderdiğiniz geri bildirimleri okumak. Bu menfaat sizinkinin önüne geçmez: ayrıştırma yalnızca uygulamada değil, veritabanının kendisindedir.",
        "legal.privacy.whyLegal": "**Yasal yükümlülük** — faturalama veya muhasebenin istediğini, öngörülen süre boyunca saklamak.",
        "legal.privacy.whyConsent": "**Rıza** — bir dersi paylaşmayı, kamerayı açmayı veya Apple ya da Google ile giriş yapmayı seçtiğinizde.",
        "legal.privacy.accessTitle": "Kim erişir",
        "legal.privacy.accessBody": "Derslerinizi, paylaşmadıysanız yalnızca siz okuyabilirsiniz. Veritabanına her istek kimliğinizle değerlendirilir: başkasının derslerini isteyebilecek bir sorgu yoktur. Gönderdiğiniz geri bildirimleri ekip [[contact]] adresinden okur. Uygulamadan başka kimsenin erişimi yoktur.",
        "legal.privacy.accessLead": "Hizmeti sağlamak için bazı yükleniciler verilerin bir kısmını görür:",
        "legal.privacy.accessSupabase": "**Supabase** (Avrupa Birliği, Stockholm bölgesi) — hesap, veritabanı, dosyalar.",
        "legal.privacy.accessVercel": "**Vercel** — sitenin barındırılması, teknik günlükler (IP adresi, URL) ve kitle ölçümü: görüntülenen sayfa sayısı, geldiğiniz sayfa, ülke ve cihaz türü; çerezsiz ve sizi izleyen bir tanımlayıcı olmadan. İşleme, yüklenicinin standart sözleşme maddeleri altında Avrupa Birliği dışında da olabilir.",
        "legal.privacy.accessApple": "**Apple ve Google** — onlarla giriş yaparsanız veya App Store'da (Apple) ya da Google Play'de (Google) öderseniz.",
        "legal.privacy.accessStripe": "**Stripe** — sitedeki ödeme.",
        "legal.privacy.accessRevenuecat": "**RevenueCat** — abonelik durumu, iPhone, Android ve site arasında paylaşılır.",
        "legal.privacy.accessFal": "**fal.ai ve çağırdığı modeller** (bugün, özellikle Google'ın dil modelleri) — dersinizin metni veya görseli, özet kâğıdını veya kartları yazdığı süre. Bunları bu üretimden başka bir şey için kullanma hakları yoktur.",
        "legal.privacy.accessYoutube": "**YouTube / Google** — bir video içe aktarırsanız meta verilerini ve altyazılarını okuruz.",
        "legal.privacy.accessTransfer": "Bu yüklenicilerden bazıları Avrupa Birliği dışında kuruludur. Aktarım o zaman yalnızca hizmeti sağlamak için olur ve GDPR'nin öngördüğü güvencelere dayanır (yeterlilik kararı veya yüklenicinin standart sözleşme maddeleri).",
        "legal.privacy.cookiesTitle": "Çerezler ve izleyiciler",
        "legal.privacy.cookiesWeb": "Site, oturum için gerekli çerezleri (bağlandıktan sonra sizi bir sayfadan ötekine tanımak) ve bir yıl saklanan, arayüz için seçtiğiniz dili tutan bir arayüz dili çerezi (`micabo.ui_locale`) koyar. Giriş yaptıktan sonra, bir yıl saklanan bir `micabo.learner` çerezi bu tarayıcıda tam seviyenizi ve karşılama yolunda verdiğiniz notları tutar: yalnızca derslerinizi doğru seviyede yazmaya yarar. Kitle ölçümü, reklam veya siteler arası izleme çerezi koymuyoruz. Site ziyaretlerini elbette sayıyor, ama cihazınıza hiçbir şey yazmadan: ölçüm bir sayfa görüntülemesini, nereden geldiğini, bir ülkeyi ve bir cihaz türünü tutar; sizi bir ziyaretten ötekine ya da başka bir sitede tanımaya yarayacak hiçbir şeyi tutmaz. Bu yüzden bir onay şeridi yoktur: o tarafta reddedecek bir şey yoktur.",
        "legal.privacy.cookiesIos": "iPhone ve Android uygulamaları çerez kullanmaz. Oturum jetonunu cihazın korumalı depolamasında tutarlar: iPhone'da anahtarlıkta, Android'de uygulamanın özel depolamasında.",
        "legal.privacy.retentionTitle": "Ne kadar saklarız",
        "legal.privacy.retentionWhile": "Hesap durduğu sürece. Geri bildirimler en geç 24 ayda gider. Sitede veya iPhone ve Android uygulamalarında Ayarlar'dan, ya da bize yazarak silerseniz profili, dersleri (çıkarılan metin dahil), özet kâğıtlarını, kartları, geçmişi, sınavları, arkadaşlıkları, kullanım sayaçlarını, geri bildirimleri ve bekleme listesinde bırakılmış adresi sileriz.",
        "legal.privacy.retentionShared": "Paylaştığınız bir ders, sildiğinizde arkadaşlarınız için kaybolur. Kartlarınızı zaten tekrarlamış bir arkadaş kendi geçmişini tutar, belgenizi değil.",
        "legal.privacy.retentionAfter": "Silmeden sonra yüklenicilerde yasanın veya sözleşmelerinin istediği kalır: Stripe, Apple veya Google faturaları, RevenueCat abonelik tanımlayıcısı, teknik günlükler (Vercel, Supabase) birkaç hafta. fal.ai metni özet kâğıdını yazdığı süre alır; saklamasını istemeyiz.",
        "legal.privacy.rightsTitle": "Haklarınız",
        "legal.privacy.rightsBody": "Verilerinize erişebilir, düzeltebilir, dışa aktarabilir, bir işlemeye itiraz edebilir veya silinmesini isteyebilirsiniz. Bir kopya indirmek için: Ayarlar → “Verilerimi indir”. Hesabı silmek için: Ayarlar → “Hesabı sil”, sitede veya iPhone ve Android uygulamalarında. [[contact]] adresine de yazabilirsiniz. Bir ay içinde yanıtlarız.",
        "legal.privacy.rightsCnil": "CNIL'e de şikâyet başvurabilirsiniz (cnil.fr).",
        "legal.privacy.minorsTitle": "Reşit olmayanlar",
        "legal.privacy.minorsBody": "Micabo öğrencilere, lise dahil, yöneliktir. Doğum tarihi sormuyoruz. On beş yaşından küçükseniz hizmet, velayet sahibinin onayıyla kullanılmalıdır. Bir küçüğün verilerini reklam veya ticari profilleme için kullanmayız.",
        "legal.privacy.iosTitle": "iPhone ve Android uygulamaları, sitenin yanı sıra",
        "legal.privacy.iosBody": "Uygulamalar, bir dersi içe aktarmak için fotoğraflarınıza, dosyalarınıza veya kameraya erişim isteyebilir. Zorunlu değildir: site yüklenen bir dosyayı kabul eder. İzin verirseniz bildirimler yalnızca bir tekrarı hatırlatır. Aynı hesap iPhone uygulamasını, Android uygulamasını ve siteyi açar.",
        "legal.privacy.changesTitle": "Değişiklikler",
        "legal.privacy.changesBody": "Bu politika esaslı biçimde değişirse sayfa başındaki tarihi güncelleriz. Bu tarihten sonraki sürekli kullanım, yasa ayrı bir onay istemedikçe, yeni sürüm için geçerlidir.",
        "legal.privacy.changesAlso": "Bu metni [[terms]] tamamlar.",
        "legal.terms.metaTitle": "Kullanım koşulları",
        "legal.terms.metaDescription": "Micabo hizmetinin iPhone, Android ve site için kuralları: hesap, dersler, abonelik, sorumluluklar.",
        "legal.terms.heading": "Kullanım koşulları",
        "legal.terms.linkLabel": "kullanım koşulları",
        "legal.terms.intro1": "Bu koşullar Micabo'nun kullanımını düzenler — [[site]] sitesi, iPhone uygulaması ({bundle}, App Store'da) ve Android uygulaması ({package}, Google Play'de). Hesap açarak veya hizmeti kullanarak bunları kabul edersiniz. Katılmıyorsanız hesap açmayın.",
        "legal.terms.intro2": "Yayımcı {editor}'dur. İletişim: [[contact]].",
        "legal.terms.serviceTitle": "Hizmet",
        "legal.terms.serviceBody": "Micabo yüklediğiniz bir ders belgesini okur ve bir özet kâğıdı ile kartlar yazar. Bunları aralıklı tekrar ile geri getirir (iPhone'da, Android'de ve sitede aynı SM-2 kuralı). Bir sınav tarihi koyabilirsiniz: tekrar planı o güne doğru sıkılaşır. Aynı hesap üç istemciyi de açar.",
        "legal.terms.servicePro": "Hizmetin bir kısmı abonelik olmadan açıktır. Pro erişim (satın alma anında gösterilen teklife göre ücretsiz tavanın ötesindeki dersler ve kartlar) ücretlidir.",
        "legal.terms.accountTitle": "Hesap",
        "legal.terms.accountBody": "Apple, Google veya e-posta ile gönderilen bir bağlantıyla giriş yapabilirsiniz. Posta kutunuza ve bu üçüncü taraf hesaplara erişimden siz sorumlusunuz. Kişi başına bir hesap.",
        "legal.terms.accountDelete": "Hesabı Ayarlar'dan silebilirsiniz, sitede veya iPhone ve Android uygulamalarında. Bu, derslerinizi, kartlarınızı ve geçmişinizi siler. Hesabı silmek, App Store'da veya Google Play'de alınmış bir aboneliği iptal etmez: onu mağazada iptal edin. Apple, Google veya Stripe'ın zaten tahsil ettiği satın alımlar, onların iade kurallarına bağlı kalır.",
        "legal.terms.coursesTitle": "Dersleriniz",
        "legal.terms.coursesOwn": "Yüklediğinizin mülkiyeti sizde kalır. Bize yalnızca, hizmeti sunmak için — üretim süresi boyunca bir dil modeline göndermek dahil — okuma, saklama ve özet kâğıdı ile kartlara dönüştürme konusunda sınırlı ve geri alınabilir bir hak verirsiniz.",
        "legal.terms.coursesRights": "Yalnızca kullanma hakkınız olan belgeler yüklersiniz. Öğretmeninizin ders notu, kendi notlarınız, içe aktarımı izinli bir video: evet. Baştan sona kopyalanmış bir eser, başkasının ödevi, yasadışı içerik: hayır. Bu kuralı bozan bir dersi kaldırabilir veya bir hesabı kapatabiliriz.",
        "legal.terms.coursesShare": "Görünürlük içe aktarmada kararlaştırılır. Özel bir ders sizde kalır. Paylaşılan bir dersi yalnızca seçtiğiniz kişiler (arkadaşlar veya okuldaki arkadaşlar) görür. Herkese açık bir kütüphane değildir.",
        "legal.terms.notTitle": "Micabo ne değildir",
        "legal.terms.notBody": "Özet kâğıdı ve kartlar otomatik üretilir. Yanılabilir, bir pasajı atlayabilir veya bir taramayı yanlış okuyabilir. Micabo bir öğretmen değildir, not garantisi de değildir. Öğrendiğinizden ve sınav günü teslim ettiğinizden siz sorumlusunuz.",
        "legal.terms.notInvent": "Belge taşımıyorsa bir tanım uydurmamaya çalışırız. Bu, sonucu yanılmaz yapmaz.",
        "legal.terms.subTitle": "Abonelik",
        "legal.terms.subPrices": "Fiyatlar, süre ve varsa deneme, ödemeden önce gösterilenlerdir. Yeni satın alımlar için değişebilir; süren bir abonelik yenilenene kadar kendi koşullarını korur.",
        "legal.terms.subIos": "**iPhone'da** ödeme App Store üzerinden geçer: iptal, yenileme ve iadeler Apple'ın kurallarını izler, abonelik Apple hesabınızın ayarlarından yönetilir veya iptal edilir (Ayarlar → adınız → Abonelikler). **Android'de** ödeme Google Play üzerinden geçer: iptal, yenileme ve iadeler Google Play'in kurallarını izler, abonelik Google Play uygulamasından yönetilir veya iptal edilir (Ödemeler ve abonelikler → Abonelikler).",
        "legal.terms.subWeb": "**Sitede** ödeme Stripe üzerinden geçer. İptal, profilde belirtilen fatura alanından veya bize yazarak yapılır. Önerilirse bir deneme, sonuna bırakırsanız ancak o zaman ödemeye dönüşür.",
        "legal.terms.subBoth": "Bir tarafta alınan Pro erişim ötekilerde de geçerlidir: aynı hesap iPhone'da, Android'de ve sitede Pro'dur. Bir ödeme aksaması bir ek süre açabilir; erişimi ilk saatte kapatmayız.",
        "legal.terms.forbidTitle": "Yapmadıklarınız",
        "legal.terms.forbidHarm": "Hizmeti birine zarar vermek, taciz etmek veya okulunuzun yönetmeliğini ihlal eden bir şekilde kopya çekmek için kullanmak.",
        "legal.terms.forbidAccess": "Başka bir hesabın derslerine erişmeye, ayrıştırmayı aşmaya veya hizmeti bile isteye yormaya çalışmak.",
        "legal.terms.forbidResell": "Erişimi satmak, hizmeti normal insan kullanımının ötesinde bir robotla çekmek veya üretimlerimizden rakip bir ürün yapmak için Micabo'yu kopyalamak.",
        "legal.terms.forbidIllegal": "Yasadışı, nefret içeren veya başkasının özel hayatına zarar veren içerik yüklemek.",
        "legal.terms.availTitle": "Erişilebilirlik",
        "legal.terms.availBody": "Uygulamaların ve sitenin ulaşılabilir kalması için elimizden geleni yaparız. Bir bakım, bir yüklenici arızası (barındırma, model, mağaza) veya bir üretim hatası hizmeti kesebilir. Okul sonucu veya kesintisiz erişilebilirlik garantisi vermiyoruz.",
        "legal.terms.liabilityTitle": "Sorumluluk",
        "legal.terms.liabilityConsumer": "Tüketicisiyseniz yasal haklarınız (garanti, arabuluculuk, haksız hükümler) geçerlidir ve bu koşullar onları ortadan kaldırmaz.",
        "legal.terms.liabilityLimit": "Bunun ötesinde Micabo alınan notlardan, eksik bir özet kâğıdından, sınav günü unutulan bir şeyden veya dolaylı bir zarardan (kayıp zaman, kaçırılan sınav) sorumlu değildir. Bize yüklenebilir bir yükümlülük ihlali için sorumluluğumuz tutulursa, son on iki ayda bize ödediğiniz tutarla sınırlıdır — ağır kusur, kast veya kişi dokunulmazlığına saldırı hariç.",
        "legal.terms.minorsTitle": "Reşit olmayanlar",
        "legal.terms.minorsBody": "On beş yaşından küçükseniz bir velayet sahibi bu koşulları kabul etmeli ve kullanımı izlemelidir. Bir dersi arkadaşlarla paylaşmak sizin ve onların sorumluluğunda kalır.",
        "legal.terms.lawTitle": "Uygulanacak hukuk",
        "legal.terms.lawBody": "Bu koşullar Fransız hukukuna tabidir. Uyuşmazlıkta ve [[contact]] adresine yazılı bir çözüm denemesinden sonra Fransız mahkemeleri yetkilidir — size daha elverişli olacak tüketici koruma kuralları saklıdır.",
        "legal.terms.changesTitle": "Değişiklikler",
        "legal.terms.changesBody": "Bu koşulları güncelleyebiliriz. Sayfa başındaki tarih geçerlidir. Süregelen bir aboneliğin fiyatını ilgilendiren bir değişiklik, yenilemeden önce size duyurulur.",
        "legal.terms.changesAlso": "Verilerinizin işlenmesini [[privacy]] anlatır.",
        "articles.shared.navAria": "Sayfalar",
        "articles.shared.nextTitle": "Sırada",
        "articles.shared.ctaTitle": "Bir konu yaz, neye dönüştüğüne bak.",
        "articles.shared.ctaBody": "Sitede de iPhone'da da, aynı hesap ve aynı derslerle.",
        "articles.method.metaTitle": "Yöntem: bir ders içinde aralıklı tekrar ve aktif hatırlama",
        "articles.method.metaDescription": "Bir dersi yeniden okumak onu akılda tutmaz. Hafızadan çıkarılan kalır, özellikle soru unutmadan hemen önce geri gelirse. Bir Micabo dersi aktif hatırlamayı ve aralıkları gerçek aralıklarla nasıl uygular.",
        "articles.method.h1": "Yeniden okumak yetmez. Hatırlamak yeter.",
        "articles.method.lead1": "Dört kez okunan bir sayfa, sınav kağıdına dayanmayan bir hakimiyet hissi verir. Gelişen şey tanımadır: «evet, bunu görmüştüm». Ve tanıma, bir sınavın istediği şey değildir.",
        "articles.method.lead2": "Kalan, **hafızadan çıkarmak** zorunda kaldığın ve **tam unutmadan önce** geri gelendir. Yüz yılı aşkın süredir ölçülen iki eski fikir, ve elle uygulaması zahmetli iki fikir. Bir Micabo dersi senin yerine bunu yapar.",
        "articles.method.activeTitle": "Aktif hatırlama: cevaptan önce soru",
        "articles.method.active1": "Kendini sınamak, yanılsan bile yeniden okumaktan daha etkilidir. İzi güçlendiren şey geri çağırma çabasıdır: üç saniye aradığın bir cevap, bir saniyede okuduğundan daha değerlidir.",
        "articles.method.active2": "Bu yüzden bir dersin her teması **bir soruyla**, her aşama bir kontrol noktasıyla biter: az önce okuduğunu geri çağırmadan devam etmezsin. Ve yanlış bir soru kaybolmaz, karta dönüşür.",
        "articles.method.spacingTitle": "Aralık: son yararlı anda geri dönmek",
        "articles.method.spacing1": "Tekrar olmadan bir dersten akılda kalan bir ayda neredeyse sıfıra düşer. Her hatırlama sayacı yüze getirir ve sonraki düşüş **öncekinden daha yavaştır**. Doğru zamanda tekrar etmek daha fazla zaman istemez: hafıza oturdukça daha az ister.",
        "articles.method.spacing2": "Önemli olan her eğrinin biçimi değil, **ayrıldıkları yer**: ilk tekrar. Bir dersin kartlarının otomatikleştirdiği, kart kart o anın seçimidir.",
        "articles.method.lessonTitle": "Önce ders, sonra kartlar",
        "articles.method.lesson1": "Bir kart, anlamış olduğunu varsayar. Okumadığın bir kavramda kendini sınamak, ne hakkında olduğunu bilmeden bir cevabı ezberlemektir. Bu yüzden Mika önce her temanın **notlarını** yazar: kısa, anahtar kelimeler belirgin ve hatırlanması gereken için bir kutu.",
        "articles.method.lessonFigure": "Bir temanın notları, Mika'nın yazdığı gibi: renkli anahtar kelime, tanım, kutu içinde **hatırlanması gereken**. Uygulamadakiyle aynı bloklar.",
        "articles.method.lesson2": "Sonra ham belgeden değil bu notlardan çıkan quiz ve kartlar gelir. Okursun, cevaplarsın ve ancak o zaman kartlar aralık ritminde geri gelir.",
        "articles.method.plannerTitle": "Micabo her puanlamada ne hesaplar",
        "articles.method.planner1": "Kartlar **SM-2** ile planlanır, Anki'nin varsayılan ayarlarındaki kural. Yeni bir kart günlere geçmeden önce kısa basamaklardan geçer, {steps}. Sonra her puan, aralığı karta özgü, {ease} ile başlayıp cevaplarınla değişen bir kolaylıkla çarpar.",
        "articles.method.planner2": "Üç düğme: Tekrar, İyi, Kolay. «Biliyorum / bilmiyorum», zorla hatırlanan kartı kendiliğinden gelenden ayırmaz ve bir sonraki tarihi belirleyen tam da bu farktır. Üç düğmenin yeni bir kartta söylediği şu:",
        "articles.method.buttonsCaption": "Aralıklar uygulamanın planlayıcısı tarafından hesaplanır, elle yazılmaz.",
        "articles.method.planner3": "Aralık, basmadan **önce** düğmenin üstünde yazar. Kendi başına karar veren bir planlayıcıya çabuk itaatsizlik edilir: hızlı gitmek için «kolay» dersin, kart üç haftalığına gider ve onu sınav günü yeniden keşfedersin.",
        "articles.method.stepMinutes": "{n} dk",
        "articles.method.stepJoin": ", sonra ",
        "articles.method.formatsTitle": "Aynı notlar hakkında sorulmanın beş yolu",
        "articles.method.formats1": "Aktif hatırlama ön-arka yüzle sınırlı değildir. Aynı temada quiz çoktan seçmeli, doğru-yanlış, boşluk doldurma, sıralama, eşleştirme sorar. Sorular notlarından gelir ve her cevap doğru mu, neden, hemen söyler.",
        "articles.method.formatsFigure": "Bir quiz sorusu, gerçeği: cevapla, seni düzeltir. **Beş biçim aynı notlardan çıkar**, en basitten en zoruna.",
        "articles.method.limitsTitle": "Yöntemin yapmadığı",
        "articles.method.limits1": "Aralıklı tekrar tekrarları yerleştirir. Senin yerine anlamaz, kompozisyon yazmaz ve bir gece önce başlanan bölümü yetiştirmez: bir gecede aralık mümkün değildir.",
        "articles.method.limits2": "Yapısı gereği tarihleri de bilmez: SM-2 üç hafta sonra sınav olduğunu bilmez. [[exam]] tam olarak bunu tamamlar.",
        "articles.method.examLink": "sınav modu",
        "articles.method.note": "Bir ders herhangi bir adımda serbestçe açılır: hiçbir şey yolu tek seferde bitirmeye zorlamaz. Aralığın istediği yalnızca kartlar söylediğinde geri dönmendir.",
        "articles.exam.metaTitle": "Sınav modu: bir tarih, kalan günler, bir deneme sınavı",
        "articles.exam.metaDescription": "Sınav tarihini ver, Micabo kapsamdaki her derste günleri sayar. Deneme sınavı sürelidir, sınav sırasında düzeltme yoktur, ülkenin not sistemine göre notlanır ve hataların karta dönüşür.",
        "articles.exam.h1": "Tarihi sen verirsin. Micabo günleri sayar ve seni çalıştırır.",
        "articles.exam.lead1": "Bir dersi öğrenmekle bir sınavı geçmek aynı şey değildir. Sınav günü süreye karşı, doğru mu görmeden yazarsın ve bir sisteme göre notlanırsın. Bunların hiçbiri sıradan bir tekrarda olmaz.",
        "articles.exam.lead2": "Sınav modu derslerine eksik olanı verir: **bir tarih** ve gerçeğine benzeyen bir sınav. Günü koyarsın, kapsamdaki dersleri seçersin ve deneme sınavlarıyla çalışırsın.",
        "articles.exam.dateTitle": "Bir tarih ve kalan günler",
        "articles.exam.date1": "Bir sınav bir ad, bir gün ve kapsadığı derslerdir. Oradan itibaren kapsamdaki her ders geri sayımını taşır: Home'da, ders listesinde ve Sınav sekmesinde. «12 gün kaldı» hiçbir şey açmadan okunur.",
        "articles.exam.date2": "Bir sınav birkaç dersi kapsayabilir, bir ders birkaç sınavda olabilir. Her zaman **en yakını** görünür: ilk kısıt odur. Gün geçince sınav geçmişlere gider, kapatılacak bir şey yoktur.",
        "articles.exam.mockTitle": "Deneme sınavı: gerçeği gibi",
        "articles.exam.mock1": "Süreyi, {durations}, ve dersleri seçersin. Mika en basitten en zoruna, beş soru biçiminde yeni bir kağıt yazar. Süre işler, seçilen cevap hükümsüz vurgulanır, geri dönersin, fikrini değiştirirsin. Sıfırda kağıt kendi kendine teslim edilir.",
        "articles.exam.mockFigure": "Teslim edilen kağıt: kendi sisteminde not, **ders ders**, ve altında her sorunun cevabı.",
        "articles.exam.mock2": "Cevap anahtarı sonda gelir, soru soru: ne cevapladığın, doğru cevap ve nedeni. Öğrenilen yer orasıdır, sınav sırasında değil; bu yüzden sınav yol boyunca hiçbir şeyi düzeltmez.",
        "articles.exam.gradeTitle": "Kendi sistemine göre notlanır",
        "articles.exam.grade1": "Yirmi üzerinden, on üzerinden, yüzde, harf, basamaklar: sistem profilinde ayarlanan ülkeni izler. Fransız 14/20, Amerikan A ve Alman 1,3 karşılaştırılamaz; evrensel bir puan hiçbir yerde bir anlam taşımazdı.",
        "articles.exam.grade2": "Kağıttaki her ders kendi notunu alır. Nereye döneceğini o söyler: sınavdan bir gün önce geçme notunun altındaki ders yeniden açılacak derstir ve yolu bekler.",
        "articles.exam.cardsTitle": "Hatalar karta dönüşür",
        "articles.exam.cards1": "Deneme sınavında kaçırılan bir soru kağıtta kalmaz. Tek dokunuşla dersinin kartlarına katılır, yarından itibaren, ve oturana kadar aralık ritminde geri gelir.",
        "articles.exam.cardsNote": "Hiçbir şey eklemeye zorlamaz. Ama bir kez görülüp bir daha bakılmayan hata, tam da sınav günü tekrarlanan hatadır.",
        "articles.exam.limitsTitle": "Sınav modunun yapmadığı",
        "articles.exam.limits1": "Zaman yaratmaz. Hiç açılmamış bir derse yarın için sınav koymak dürüst bir geri sayım ve zor bir kağıt verir; Micabo teselli etmek yerine bunları olduğu gibi gösterir.",
        "articles.exam.limits2": "[[method]] yerini de tutmaz: işi notlar, quizler ve kartlar yapar, deneme sınavı yalnızca ölçer. Anki'den geliyorsan [[anki]] neyin değiştiğini tam olarak söyler.",
        "articles.exam.methodLink": "yöntemin",
        "articles.exam.ankiLink": "karşılaştırma",
        "articles.exam.duration": "{count} soru için {minutes} dk",
        "articles.exam.durationJoin": ", ",
        "articles.anki.metaTitle": "Micabo mu Anki mi: gerçekte ne değişir",
